const WEEK11_CODES = {
  topic1: {
    title: "Semi-Infinite Medium & Finite Slab (erfc, Fourier series)",
    python: "# Week 11 - Topic 1: Unsteady 1D Diffusion - Semi-Infinite Medium and Finite Slab\n# Lecture (Part 1):\n#   * Fick's second law (1D, no reaction, no bulk motion): dc/dt = D d2c/dz2\n#   * semi-infinite medium, c(z,0) = c0, c(0,t) = cs, c(inf,t) = c0  (Laplace transform):\n#       (c - c0)/(cs - c0) = erfc( z / (2 sqrt(D t)) )\n#       surface flux  N(0,t) = (cs - c0) sqrt(D/(pi t))       (decays as t^-1/2)\n#       uptake per area  W/S = 2 (cs - c0) sqrt(D t / pi)       (grows as t^1/2)\n#   * finite slab 0 < z < L, c = cs on both faces, Y = (c - cs)/(c0 - cs):\n#       Y = (4/pi) sum_k 1/(2k-1) sin((2k-1) pi z/L) exp(-(2k-1)^2 pi^2 D t / L^2)\n#       fractional uptake  M(t)/M_inf = 1 - sum_k 8/((2k-1)^2 pi^2) exp(-(2k-1)^2 pi^2 Fo),  Fo = D t/L^2\n#   * case study (lecture): P diffusion into Si, cs = 2.5e20 cm^-3, target 2.5e18 cm^-3,\n#     D = 6.5e-13 cm^2/s at 1373 K, t = 1 h  ->  erfc(phi) = 0.01, phi = 1.82, z = 1.76 um\n# This script: (1) erfc profile, flux and uptake, (2) the doping-depth case,\n# (3) Fourier series versus a Crank-Nicolson finite-difference solution,\n# (4) when the semi-infinite (short-time) result stops being valid for a slab.\n\nimport math\n\n\ndef erfc_inv(y, lo=0.0, hi=10.0):\n    \"\"\"inverse of erfc on (0, 1] by bisection\"\"\"\n    for _ in range(200):\n        mid = 0.5 * (lo + hi)\n        if math.erfc(mid) > y:\n            lo = mid\n        else:\n            hi = mid\n    return 0.5 * (lo + hi)\n\n\ndef semi_infinite(z, t, D):\n    return math.erfc(z / (2.0 * math.sqrt(D * t)))\n\n\ndef slab_series(z, t, D, L, nterms=200):\n    s = 0.0\n    for k in range(1, nterms + 1):\n        m = 2 * k - 1\n        s += 4.0 / (m * math.pi) * math.sin(m * math.pi * z / L) * math.exp(-(m * math.pi / L) ** 2 * D * t)\n    return s  # Y = (c - cs)/(c0 - cs)\n\n\ndef slab_uptake(Fo, nterms=200):\n    s = 0.0\n    for k in range(1, nterms + 1):\n        m = 2 * k - 1\n        s += 8.0 / (m * m * math.pi ** 2) * math.exp(-(m * math.pi) ** 2 * Fo)\n    return 1.0 - s\n\n\ndef thomas(a, b, c, d):\n    n = len(d)\n    cp, dp = [0.0] * n, [0.0] * n\n    cp[0], dp[0] = c[0] / b[0], d[0] / b[0]\n    for i in range(1, n):\n        m = b[i] - a[i] * cp[i - 1]\n        cp[i] = c[i] / m if i < n - 1 else 0.0\n        dp[i] = (d[i] - a[i] * dp[i - 1]) / m\n    x = [0.0] * n\n    x[-1] = dp[-1]\n    for i in range(n - 2, -1, -1):\n        x[i] = dp[i] - cp[i] * x[i + 1]\n    return x\n\n\ndef slab_crank_nicolson(Fo_end, N=100, steps=2000):\n    \"\"\"Y on 0..1 (z/L), Y = 1 inside at t = 0, Y = 0 on both faces\"\"\"\n    h = 1.0 / N\n    dt = Fo_end / steps\n    r = dt / h ** 2\n    Y = [1.0] * (N + 1)\n    Y[0] = Y[N] = 0.0\n    n = N - 1\n    a = [-r / 2] * n\n    b = [1 + r] * n\n    c = [-r / 2] * n\n    for _ in range(steps):\n        d = [r / 2 * Y[i - 1] + (1 - r) * Y[i] + r / 2 * Y[i + 1] for i in range(1, N)]\n        Y[1:N] = thomas(a, b, c, d)\n    return Y\n\n\nif __name__ == \"__main__\":\n    print(\"=== 1. Semi-infinite medium: profile, flux, uptake ===\")\n    D = 1.0e-9          # m^2/s (a small solute in water)\n    dc = 1.0            # cs - c0, mol/m^3\n    for t in (10.0, 100.0, 1000.0):\n        delta = math.sqrt(D * t)\n        flux = dc * math.sqrt(D / (math.pi * t))\n        up = 2 * dc * math.sqrt(D * t / math.pi)\n        print(f\"t = {t:7.0f} s: sqrt(Dt) = {delta*1e6:7.1f} um, \"\n              f\"N(0) = {flux:.3e} mol/m2/s, uptake = {up:.3e} mol/m2\")\n    print(f\"  N(0) x sqrt(t) = dc sqrt(D/pi) = {dc*math.sqrt(D/math.pi):.4e} for every t\")\n\n    print(\"\\n=== 2. Case: P doping of Si (lecture) ===\")\n    cs, ctarget = 2.5e20, 2.5e18          # atoms/cm^3\n    Dp, t = 6.5e-13, 3600.0                # cm^2/s, s\n    phi = erfc_inv(ctarget / cs)\n    z = 2 * phi * math.sqrt(Dp * t)\n    print(f\"erfc(phi) = {ctarget/cs:.3f}  ->  phi = {phi:.3f}\")\n    print(f\"depth for 2.5e18 cm^-3 after 1 h at 1373 K: z = {z*1e4:.2f} um   (lecture: 1.76 um)\")\n    for hours in (0.25, 1, 4):\n        print(f\"  t = {hours:4.2f} h -> z = {2*phi*math.sqrt(Dp*hours*3600)*1e4:.2f} um  (depth ~ sqrt(t))\")\n\n    print(\"\\n=== 3. Finite slab: Fourier series vs Crank-Nicolson ===\")\n    for Fo in (0.01, 0.05, 0.2):\n        Ycn = slab_crank_nicolson(Fo)\n        err = max(abs(Ycn[i] - slab_series(i / 100, Fo, 1.0, 1.0)) for i in range(101))\n        print(f\"Fo = {Fo:4.2f}: Y(centre) series = {slab_series(0.5, Fo, 1, 1):.5f}, \"\n              f\"CN = {Ycn[50]:.5f}, max |diff| = {err:.1e}\")\n    print(\"terms needed at t = 0+ (Gibbs): the series converges slowly near the faces;\")\n    for nt in (1, 5, 50):\n        print(f\"  {nt:3d} terms: Y(z/L = 0.02, Fo = 0) = {slab_series(0.02, 0.0, 1, 1, nt):.3f} (exact 1)\")\n\n    print(\"\\n=== 4. When is a slab 'semi-infinite'? ===\")\n    print(\"  Fo      exact M/Minf   short-time 4 sqrt(Fo/pi)   error\")\n    for Fo in (0.001, 0.01, 0.03, 0.05, 0.1, 0.2):\n        ex = slab_uptake(Fo)\n        st = 4 * math.sqrt(Fo / math.pi)\n        print(f\"  {Fo:5.3f}   {ex:.4f}         {st:.4f}                  {100*(st-ex)/ex:6.2f}%\")\n    print(\"-> the two faces do not 'see' each other until Fo ~ 0.05 (error about 0.1%)\")\n",
    matlab: "% Week 11 - Topic 1: Unsteady 1D Diffusion - Semi-Infinite Medium and Finite Slab\n% Lecture (Part 1):\n%   * Fick's second law (1D, no reaction, no bulk motion): dc/dt = D d2c/dz2\n%   * semi-infinite medium, c(z,0) = c0, c(0,t) = cs, c(inf,t) = c0  (Laplace transform):\n%       (c - c0)/(cs - c0) = erfc( z / (2 sqrt(D t)) )\n%       surface flux  N(0,t) = (cs - c0) sqrt(D/(pi t))       (decays as t^-1/2)\n%       uptake per area  W/S = 2 (cs - c0) sqrt(D t / pi)       (grows as t^1/2)\n%   * finite slab 0 < z < L, c = cs on both faces, Y = (c - cs)/(c0 - cs):\n%       Y = (4/pi) sum_k 1/(2k-1) sin((2k-1) pi z/L) exp(-(2k-1)^2 pi^2 D t / L^2)\n%       fractional uptake  M(t)/M_inf = 1 - sum_k 8/((2k-1)^2 pi^2) exp(-(2k-1)^2 pi^2 Fo),  Fo = D t/L^2\n%   * case study (lecture): P diffusion into Si, cs = 2.5e20 cm^-3, target 2.5e18 cm^-3,\n%     D = 6.5e-13 cm^2/s at 1373 K, t = 1 h  ->  erfc(phi) = 0.01, phi = 1.82, z = 1.76 um\n% Run: week11_topic1_slab_semi_infinite   (MATLAB R2016b or later, local functions at the end)\n\nfprintf('=== 1. Semi-infinite medium: profile, flux, uptake ===\\n');\nD = 1.0e-9; dc = 1.0;\nfor t = [10 100 1000]\n    fprintf('t = %7.0f s: sqrt(Dt) = %7.1f um, N(0) = %.3e mol/m2/s, uptake = %.3e mol/m2\\n', ...\n        t, sqrt(D*t)*1e6, dc*sqrt(D/(pi*t)), 2*dc*sqrt(D*t/pi));\nend\nfprintf('  N(0) x sqrt(t) = dc sqrt(D/pi) = %.4e for every t\\n', dc*sqrt(D/pi));\n\nfprintf('\\n=== 2. Case: P doping of Si (lecture) ===\\n');\ncs = 2.5e20; ct = 2.5e18; Dp = 6.5e-13; tt = 3600;\nphi = erfc_inv_bisect(ct/cs);\nfprintf('erfc(phi) = %.3f  ->  phi = %.3f\\n', ct/cs, phi);\nfprintf('depth for 2.5e18 cm^-3 after 1 h at 1373 K: z = %.2f um   (lecture: 1.76 um)\\n', 2*phi*sqrt(Dp*tt)*1e4);\nfor hrs = [0.25 1 4]\n    fprintf('  t = %4.2f h -> z = %.2f um  (depth ~ sqrt(t))\\n', hrs, 2*phi*sqrt(Dp*hrs*3600)*1e4);\nend\n\nfprintf('\\n=== 3. Finite slab: Fourier series vs Crank-Nicolson ===\\n');\nfor Fo = [0.01 0.05 0.2]\n    Y = slab_cn(Fo, 100, 2000);\n    zz = (0:100)/100;\n    err = max(abs(Y - slab_series(zz, Fo, 1, 1, 200)));\n    fprintf('Fo = %4.2f: Y(centre) series = %.5f, CN = %.5f, max |diff| = %.1e\\n', ...\n        Fo, slab_series(0.5, Fo, 1, 1, 200), Y(51), err);\nend\nfprintf('terms needed at t = 0+ (Gibbs): the series converges slowly near the faces;\\n');\nfor nt = [1 5 50]\n    fprintf('  %3d terms: Y(z/L = 0.02, Fo = 0) = %.3f (exact 1)\\n', nt, slab_series(0.02, 0, 1, 1, nt));\nend\n\nfprintf('\\n=== 4. When is a slab ''semi-infinite''? ===\\n');\nfprintf('  Fo      exact M/Minf   short-time 4 sqrt(Fo/pi)   error\\n');\nfor Fo = [0.001 0.01 0.03 0.05 0.1 0.2]\n    ex = slab_uptake(Fo, 200); st = 4*sqrt(Fo/pi);\n    fprintf('  %5.3f   %.4f         %.4f                  %6.2f%%\\n', Fo, ex, st, 100*(st-ex)/ex);\nend\nfprintf('-> the two faces do not ''see'' each other until Fo ~ 0.05 (error about 0.1%%)\\n');\n\n% ------------------------------------------------------------------ local functions\nfunction x = erfc_inv_bisect(y)\n    lo = 0; hi = 10;\n    for i = 1:200\n        mid = 0.5*(lo + hi);\n        if erfc(mid) > y, lo = mid; else, hi = mid; end\n    end\n    x = 0.5*(lo + hi);\nend\n\nfunction Y = slab_series(z, t, D, L, nterms)\n    Y = zeros(size(z));\n    for k = 1:nterms\n        m = 2*k - 1;\n        Y = Y + 4/(m*pi) * sin(m*pi*z/L) * exp(-(m*pi/L)^2*D*t);\n    end\nend\n\nfunction M = slab_uptake(Fo, nterms)\n    s = 0;\n    for k = 1:nterms\n        m = 2*k - 1;\n        s = s + 8/(m^2*pi^2) * exp(-(m*pi)^2*Fo);\n    end\n    M = 1 - s;\nend\n\nfunction Y = slab_cn(FoEnd, N, steps)\n    h = 1/N; dt = FoEnd/steps; r = dt/h^2;\n    Y = ones(1, N+1); Y(1) = 0; Y(end) = 0;\n    n = N - 1;\n    A = spdiags([-r/2*ones(n,1), (1+r)*ones(n,1), -r/2*ones(n,1)], -1:1, n, n);\n    for s = 1:steps\n        d = r/2*Y(1:N-1) + (1-r)*Y(2:N) + r/2*Y(3:N+1);\n        Y(2:N) = (A \\ d.').';\n    end\nend\n",
    julia: "# Week 11 - Topic 1: Unsteady 1D Diffusion - Semi-Infinite Medium and Finite Slab\n# Lecture (Part 1):\n#   * Fick's second law (1D, no reaction, no bulk motion): dc/dt = D d2c/dz2\n#   * semi-infinite medium, c(z,0) = c0, c(0,t) = cs, c(inf,t) = c0  (Laplace transform):\n#       (c - c0)/(cs - c0) = erfc( z / (2 sqrt(D t)) )\n#       surface flux  N(0,t) = (cs - c0) sqrt(D/(pi t))       (decays as t^-1/2)\n#       uptake per area  W/S = 2 (cs - c0) sqrt(D t / pi)       (grows as t^1/2)\n#   * finite slab 0 < z < L, c = cs on both faces, Y = (c - cs)/(c0 - cs):\n#       Y = (4/pi) sum_k 1/(2k-1) sin((2k-1) pi z/L) exp(-(2k-1)^2 pi^2 D t / L^2)\n#       fractional uptake  M(t)/M_inf = 1 - sum_k 8/((2k-1)^2 pi^2) exp(-(2k-1)^2 pi^2 Fo),  Fo = D t/L^2\n#   * case study (lecture): P diffusion into Si, cs = 2.5e20 cm^-3, target 2.5e18 cm^-3,\n#     D = 6.5e-13 cm^2/s at 1373 K, t = 1 h  ->  erfc(phi) = 0.01, phi = 1.82, z = 1.76 um\n# Run: julia week11_topic1_slab_semi_infinite.jl   (no packages needed; erfc is coded below)\n\nusing Printf\n\n# complementary error function: erfc(x) = exp(-x^2) * continued-fraction / series (accurate to ~1e-15)\nfunction erfc_(x::Float64)\n    if x < 0\n        return 2.0 - erfc_(-x)\n    elseif x < 2.0\n        # series for erf\n        s, term, n = x, x, 0\n        while abs(term) > 1e-17 * abs(s)\n            n += 1\n            term *= -x^2 / n\n            s += term / (2n + 1)\n        end\n        return 1.0 - 2.0 / sqrt(pi) * s\n    else\n        # Lentz continued fraction\n        f = x; C = x; Dd = 0.0\n        for n in 1:300\n            an = n / 2\n            Dd = x + an * Dd; Dd = 1 / Dd\n            C = x + an / C\n            delta = C * Dd\n            f *= delta\n            abs(delta - 1) < 1e-16 && break\n        end\n        return exp(-x^2) / (f * sqrt(pi))\n    end\nend\n\nfunction erfc_inv(y)\n    lo, hi = 0.0, 10.0\n    for _ in 1:200\n        mid = 0.5 * (lo + hi)\n        erfc_(mid) > y ? (lo = mid) : (hi = mid)\n    end\n    return 0.5 * (lo + hi)\nend\n\nslab_series(z, t, D, L, nterms=200) =\n    sum(4 / ((2k - 1) * pi) * sin((2k - 1) * pi * z / L) * exp(-((2k - 1) * pi / L)^2 * D * t) for k in 1:nterms)\n\nslab_uptake(Fo, nterms=200) = 1 - sum(8 / ((2k - 1)^2 * pi^2) * exp(-((2k - 1) * pi)^2 * Fo) for k in 1:nterms)\n\nfunction thomas(a, b, c, d)\n    n = length(d)\n    cp = zeros(n); dp = zeros(n); x = zeros(n)\n    cp[1] = c[1] / b[1]; dp[1] = d[1] / b[1]\n    for i in 2:n\n        m = b[i] - a[i] * cp[i-1]\n        cp[i] = i < n ? c[i] / m : 0.0\n        dp[i] = (d[i] - a[i] * dp[i-1]) / m\n    end\n    x[n] = dp[n]\n    for i in n-1:-1:1\n        x[i] = dp[i] - cp[i] * x[i+1]\n    end\n    return x\nend\n\nfunction slab_cn(FoEnd; N=100, steps=2000)\n    h = 1 / N; dt = FoEnd / steps; r = dt / h^2\n    Y = ones(N + 1); Y[1] = 0.0; Y[end] = 0.0\n    n = N - 1\n    a = fill(-r / 2, n); b = fill(1 + r, n); c = fill(-r / 2, n)\n    for _ in 1:steps\n        d = [r / 2 * Y[i-1] + (1 - r) * Y[i] + r / 2 * Y[i+1] for i in 2:N]\n        Y[2:N] = thomas(a, b, c, d)\n    end\n    return Y\nend\n\nprintln(\"=== 1. Semi-infinite medium: profile, flux, uptake ===\")\nD, dc = 1.0e-9, 1.0\nfor t in (10.0, 100.0, 1000.0)\n    @printf(\"t = %7.0f s: sqrt(Dt) = %7.1f um, N(0) = %.3e mol/m2/s, uptake = %.3e mol/m2\\n\",\n            t, sqrt(D * t) * 1e6, dc * sqrt(D / (pi * t)), 2 * dc * sqrt(D * t / pi))\nend\n@printf(\"  N(0) x sqrt(t) = dc sqrt(D/pi) = %.4e for every t\\n\", dc * sqrt(D / pi))\n\nprintln(\"\\n=== 2. Case: P doping of Si (lecture) ===\")\ncs, ct, Dp, tt = 2.5e20, 2.5e18, 6.5e-13, 3600.0\nphi = erfc_inv(ct / cs)\n@printf(\"erfc(phi) = %.3f  ->  phi = %.3f\\n\", ct / cs, phi)\n@printf(\"depth for 2.5e18 cm^-3 after 1 h at 1373 K: z = %.2f um   (lecture: 1.76 um)\\n\", 2 * phi * sqrt(Dp * tt) * 1e4)\nfor hrs in (0.25, 1.0, 4.0)\n    @printf(\"  t = %4.2f h -> z = %.2f um  (depth ~ sqrt(t))\\n\", hrs, 2 * phi * sqrt(Dp * hrs * 3600) * 1e4)\nend\n\nprintln(\"\\n=== 3. Finite slab: Fourier series vs Crank-Nicolson ===\")\nfor Fo in (0.01, 0.05, 0.2)\n    Y = slab_cn(Fo)\n    err = maximum(abs(Y[i+1] - slab_series(i / 100, Fo, 1, 1)) for i in 0:100)\n    @printf(\"Fo = %4.2f: Y(centre) series = %.5f, CN = %.5f, max |diff| = %.1e\\n\", Fo, slab_series(0.5, Fo, 1, 1), Y[51], err)\nend\nprintln(\"terms needed at t = 0+ (Gibbs): the series converges slowly near the faces;\")\nfor nt in (1, 5, 50)\n    @printf(\"  %3d terms: Y(z/L = 0.02, Fo = 0) = %.3f (exact 1)\\n\", nt, slab_series(0.02, 0.0, 1, 1, nt))\nend\n\nprintln(\"\\n=== 4. When is a slab 'semi-infinite'? ===\")\nprintln(\"  Fo      exact M/Minf   short-time 4 sqrt(Fo/pi)   error\")\nfor Fo in (0.001, 0.01, 0.03, 0.05, 0.1, 0.2)\n    ex = slab_uptake(Fo); st = 4 * sqrt(Fo / pi)\n    @printf(\"  %5.3f   %.4f         %.4f                  %6.2f%%\\n\", Fo, ex, st, 100 * (st - ex) / ex)\nend\nprintln(\"-> the two faces do not 'see' each other until Fo ~ 0.05 (error about 0.1%)\")\n",
    cpp: "// Week 11 - Topic 1: Unsteady 1D Diffusion - Semi-Infinite Medium and Finite Slab\n// Lecture (Part 1):\n//   * Fick's second law (1D, no reaction, no bulk motion): dc/dt = D d2c/dz2\n//   * semi-infinite medium, c(z,0) = c0, c(0,t) = cs, c(inf,t) = c0  (Laplace transform):\n//       (c - c0)/(cs - c0) = erfc( z / (2 sqrt(D t)) )\n//       surface flux  N(0,t) = (cs - c0) sqrt(D/(pi t))       (decays as t^-1/2)\n//       uptake per area  W/S = 2 (cs - c0) sqrt(D t / pi)       (grows as t^1/2)\n//   * finite slab 0 < z < L, c = cs on both faces, Y = (c - cs)/(c0 - cs):\n//       Y = (4/pi) sum_k 1/(2k-1) sin((2k-1) pi z/L) exp(-(2k-1)^2 pi^2 D t / L^2)\n//       fractional uptake  M(t)/M_inf = 1 - sum_k 8/((2k-1)^2 pi^2) exp(-(2k-1)^2 pi^2 Fo),  Fo = D t/L^2\n//   * case study (lecture): P diffusion into Si, cs = 2.5e20 cm^-3, target 2.5e18 cm^-3,\n//     D = 6.5e-13 cm^2/s at 1373 K, t = 1 h  ->  erfc(phi) = 0.01, phi = 1.82, z = 1.76 um\n// Build: g++ -O2 -std=c++17 week11_topic1_slab_semi_infinite.cpp -o topic1\n#include <cmath>\n#include <cstdio>\n#include <initializer_list>\n#include <vector>\n\nconst double PI = 3.14159265358979323846;\n\ndouble erfcInv(double y) {\n    double lo = 0.0, hi = 10.0;\n    for (int i = 0; i < 200; ++i) {\n        double mid = 0.5 * (lo + hi);\n        if (std::erfc(mid) > y) lo = mid; else hi = mid;\n    }\n    return 0.5 * (lo + hi);\n}\n\ndouble slabSeries(double z, double t, double D, double L, int nterms = 200) {\n    double s = 0.0;\n    for (int k = 1; k <= nterms; ++k) {\n        int m = 2 * k - 1;\n        s += 4.0 / (m * PI) * std::sin(m * PI * z / L) * std::exp(-std::pow(m * PI / L, 2) * D * t);\n    }\n    return s;\n}\n\ndouble slabUptake(double Fo, int nterms = 200) {\n    double s = 0.0;\n    for (int k = 1; k <= nterms; ++k) {\n        int m = 2 * k - 1;\n        s += 8.0 / (m * m * PI * PI) * std::exp(-std::pow(m * PI, 2) * Fo);\n    }\n    return 1.0 - s;\n}\n\nstd::vector<double> thomas(const std::vector<double>& a, const std::vector<double>& b,\n                           const std::vector<double>& c, const std::vector<double>& d) {\n    size_t n = d.size();\n    std::vector<double> cp(n), dp(n), x(n);\n    cp[0] = c[0] / b[0]; dp[0] = d[0] / b[0];\n    for (size_t i = 1; i < n; ++i) {\n        double m = b[i] - a[i] * cp[i - 1];\n        cp[i] = (i < n - 1) ? c[i] / m : 0.0;\n        dp[i] = (d[i] - a[i] * dp[i - 1]) / m;\n    }\n    x[n - 1] = dp[n - 1];\n    for (int i = (int)n - 2; i >= 0; --i) x[i] = dp[i] - cp[i] * x[i + 1];\n    return x;\n}\n\nstd::vector<double> slabCrankNicolson(double FoEnd, int N = 100, int steps = 2000) {\n    double h = 1.0 / N, dt = FoEnd / steps, r = dt / (h * h);\n    std::vector<double> Y(N + 1, 1.0);\n    Y[0] = Y[N] = 0.0;\n    int n = N - 1;\n    std::vector<double> a(n, -r / 2), b(n, 1 + r), c(n, -r / 2), d(n);\n    for (int s = 0; s < steps; ++s) {\n        for (int i = 1; i < N; ++i) d[i - 1] = r / 2 * Y[i - 1] + (1 - r) * Y[i] + r / 2 * Y[i + 1];\n        std::vector<double> x = thomas(a, b, c, d);\n        for (int i = 1; i < N; ++i) Y[i] = x[i - 1];\n    }\n    return Y;\n}\n\nint main() {\n    std::printf(\"=== 1. Semi-infinite medium: profile, flux, uptake ===\\n\");\n    double D = 1.0e-9, dc = 1.0;\n    for (double t : {10.0, 100.0, 1000.0}) {\n        std::printf(\"t = %7.0f s: sqrt(Dt) = %7.1f um, N(0) = %.3e mol/m2/s, uptake = %.3e mol/m2\\n\",\n                    t, std::sqrt(D * t) * 1e6, dc * std::sqrt(D / (PI * t)), 2 * dc * std::sqrt(D * t / PI));\n    }\n    std::printf(\"  N(0) x sqrt(t) = dc sqrt(D/pi) = %.4e for every t\\n\", dc * std::sqrt(D / PI));\n\n    std::printf(\"\\n=== 2. Case: P doping of Si (lecture) ===\\n\");\n    double cs = 2.5e20, ct = 2.5e18, Dp = 6.5e-13, tt = 3600.0;\n    double phi = erfcInv(ct / cs);\n    std::printf(\"erfc(phi) = %.3f  ->  phi = %.3f\\n\", ct / cs, phi);\n    std::printf(\"depth for 2.5e18 cm^-3 after 1 h at 1373 K: z = %.2f um   (lecture: 1.76 um)\\n\",\n                2 * phi * std::sqrt(Dp * tt) * 1e4);\n    for (double hrs : {0.25, 1.0, 4.0})\n        std::printf(\"  t = %4.2f h -> z = %.2f um  (depth ~ sqrt(t))\\n\", hrs, 2 * phi * std::sqrt(Dp * hrs * 3600) * 1e4);\n\n    std::printf(\"\\n=== 3. Finite slab: Fourier series vs Crank-Nicolson ===\\n\");\n    for (double Fo : {0.01, 0.05, 0.2}) {\n        std::vector<double> Y = slabCrankNicolson(Fo);\n        double err = 0.0;\n        for (int i = 0; i <= 100; ++i) err = std::fmax(err, std::fabs(Y[i] - slabSeries(i / 100.0, Fo, 1, 1)));\n        std::printf(\"Fo = %4.2f: Y(centre) series = %.5f, CN = %.5f, max |diff| = %.1e\\n\",\n                    Fo, slabSeries(0.5, Fo, 1, 1), Y[50], err);\n    }\n    std::printf(\"terms needed at t = 0+ (Gibbs): the series converges slowly near the faces;\\n\");\n    for (int nt : {1, 5, 50})\n        std::printf(\"  %3d terms: Y(z/L = 0.02, Fo = 0) = %.3f (exact 1)\\n\", nt, slabSeries(0.02, 0.0, 1, 1, nt));\n\n    std::printf(\"\\n=== 4. When is a slab 'semi-infinite'? ===\\n\");\n    std::printf(\"  Fo      exact M/Minf   short-time 4 sqrt(Fo/pi)   error\\n\");\n    for (double Fo : {0.001, 0.01, 0.03, 0.05, 0.1, 0.2}) {\n        double ex = slabUptake(Fo), st = 4 * std::sqrt(Fo / PI);\n        std::printf(\"  %5.3f   %.4f         %.4f                  %6.2f%%\\n\", Fo, ex, st, 100 * (st - ex) / ex);\n    }\n    std::printf(\"-> the two faces do not 'see' each other until Fo ~ 0.05 (error about 0.1%%)\\n\");\n    return 0;\n}\n",
  },
  topic2: {
    title: "Sphere: Drug Release from a Gel Bead",
    python: "# Week 11 - Topic 2: Transient Diffusion in a Sphere - Drug Release from a Gel Bead\n# Lecture (Part 1):\n#   dc/dt = D (d2c/dr2 + (2/r) dc/dr),  c(R,t) = cs = 0 (perfect sink),  dc/dr(0,t) = 0,  c(r,0) = c0\n#   (c - c0)/(cs - c0) = 1 + (2R/(pi r)) sum_n (-1)^n/n sin(n pi r/R) exp(-n^2 pi^2 D t/R^2)\n#   centre (r -> 0, sin x/x -> 1):  (c(0,t) - c0)/(cs - c0) = 1 + 2 sum_n (-1)^n exp(-n^2 pi^2 tau)\n#   release rate   W(t) = 8 pi c0 D R sum_n exp(-n^2 pi^2 tau)\n#   remaining      m(t)/m0 = (6/pi^2) sum_n (1/n^2) exp(-n^2 pi^2 tau),   tau = D t / R^2\n#   long times (one term): m/m0 ~ (6/pi^2) exp(-pi^2 tau)  (the lecture writes ~ exp(-pi^2 tau))\n#   short times: released fraction ~ 6 sqrt(tau/pi) - 3 tau  (semi-infinite limit with curvature)\n# This script: series solution, a finite-volume check in spherical coordinates,\n# half-release and 90%-release times, and how release time scales with bead radius.\n\nimport math\n\n\ndef remaining_fraction(tau, nterms=400):\n    if tau <= 0:\n        return 1.0\n    return 6.0 / math.pi ** 2 * sum(math.exp(-(n * math.pi) ** 2 * tau) / n ** 2 for n in range(1, nterms + 1))\n\n\ndef theta(rho, tau, nterms=400):\n    \"\"\"c/c0 inside the bead (sink at the surface, cs = 0)\"\"\"\n    if tau <= 0:\n        return 1.0\n    s = 0.0\n    for n in range(1, nterms + 1):\n        e = math.exp(-(n * math.pi) ** 2 * tau)\n        if e < 1e-300:\n            break\n        shape = n * math.pi if rho < 1e-12 else math.sin(n * math.pi * rho) / rho\n        s += 2.0 * (-1) ** (n + 1) / (n * math.pi) * shape * e\n    return s   # c/c0 = (2/(pi rho)) sum (-1)^(n+1)/n sin(n pi rho) exp(-n^2 pi^2 tau)\n\n\ndef tau_for(remaining):\n    lo, hi = 1e-8, 5.0\n    for _ in range(200):\n        mid = math.sqrt(lo * hi)\n        if remaining_fraction(mid) > remaining:\n            lo = mid\n        else:\n            hi = mid\n    return math.sqrt(lo * hi)\n\n\ndef finite_volume(tau_end, N=200, steps=40000):\n    \"\"\"explicit finite volume on N shells, returns (centre c/c0, remaining fraction)\"\"\"\n    dr = 1.0 / N\n    rc = [(i + 0.5) * dr for i in range(N)]\n    vol = [((i + 1) ** 3 - i ** 3) * dr ** 3 / 3.0 for i in range(N)]\n    area = [(i + 1) ** 2 * dr ** 2 for i in range(N)]       # outer face of shell i (4 pi dropped)\n    dt = tau_end / steps\n    assert dt < 0.5 * dr * dr / 3.0, \"explicit step too large\"\n    c = [1.0] * N\n    for _ in range(steps):\n        flux = [0.0] * N\n        for i in range(N - 1):\n            flux[i] = -area[i] * (c[i + 1] - c[i]) / dr\n        flux[N - 1] = -area[N - 1] * (0.0 - c[N - 1]) / (0.5 * dr)\n        new = c[:]\n        for i in range(N):\n            inflow = (flux[i - 1] if i > 0 else 0.0) - flux[i]\n            new[i] = c[i] + dt * inflow / vol[i]\n        c = new\n    m = sum(ci * vi for ci, vi in zip(c, vol)) * 3.0     # total volume = 1/3\n    return c[0], m\n\n\nif __name__ == \"__main__\":\n    print(\"=== 1. Series solution: centre concentration and remaining drug ===\")\n    print(\"  tau      c(0)/c0    m/m0 (series)   one-term (6/pi^2)e^(-pi^2 tau)\")\n    for tau in (0.01, 0.03, 0.05, 0.1, 0.2, 0.3):\n        print(f\"  {tau:5.2f}    {theta(0.0, tau):.5f}    {remaining_fraction(tau):.5f}        \"\n              f\"{6/math.pi**2*math.exp(-math.pi**2*tau):.5f}\")\n\n    print(\"\\n=== 2. Check against a finite-volume solution (200 shells) ===\")\n    for tau in (0.03, 0.1):\n        c0, m = finite_volume(tau)\n        print(f\"  tau = {tau:4.2f}: centre FV = {c0:.4f} vs series {theta(0.5/200, tau):.4f}; \"\n              f\"m/m0 FV = {m:.4f} vs series {remaining_fraction(tau):.4f}\")\n\n    print(\"\\n=== 3. Characteristic release times ===\")\n    t50, t90 = tau_for(0.5), tau_for(0.1)\n    print(f\"  50% released at tau = {t50:.4f};  90% released at tau = {t90:.4f}\")\n    print(f\"  short-time check: 6 sqrt(tau/pi) - 3 tau at tau_50 = {6*math.sqrt(t50/math.pi)-3*t50:.4f} (should be 0.5)\")\n\n    print(\"\\n=== 4. Case: release from hydrogel beads (illustrative diffusivities) ===\")\n    for name, D in ((\"small drug, D = 5e-10 m^2/s\", 5e-10), (\"protein, D = 1e-11 m^2/s\", 1e-11)):\n        print(\"  \" + name)\n        for R_mm in (0.1, 0.5, 1.0, 2.0):\n            R = R_mm * 1e-3\n            print(f\"    R = {R_mm:3.1f} mm: t50 = {t50*R*R/D/60:8.2f} min, t90 = {t90*R*R/D/60:8.1f} min\")\n    print(\"  -> release time scales as R^2/D: halving the bead radius releases four times faster\")\n",
    matlab: "% Week 11 - Topic 2: Transient Diffusion in a Sphere - Drug Release from a Gel Bead\n% Lecture (Part 1):\n%   dc/dt = D (d2c/dr2 + (2/r) dc/dr),  c(R,t) = cs = 0 (perfect sink),  dc/dr(0,t) = 0,  c(r,0) = c0\n%   (c - c0)/(cs - c0) = 1 + (2R/(pi r)) sum_n (-1)^n/n sin(n pi r/R) exp(-n^2 pi^2 D t/R^2)\n%   centre (r -> 0, sin x/x -> 1):  (c(0,t) - c0)/(cs - c0) = 1 + 2 sum_n (-1)^n exp(-n^2 pi^2 tau)\n%   release rate   W(t) = 8 pi c0 D R sum_n exp(-n^2 pi^2 tau)\n%   remaining      m(t)/m0 = (6/pi^2) sum_n (1/n^2) exp(-n^2 pi^2 tau),   tau = D t / R^2\n%   long times (one term): m/m0 ~ (6/pi^2) exp(-pi^2 tau)  (the lecture writes ~ exp(-pi^2 tau))\n%   short times: released fraction ~ 6 sqrt(tau/pi) - 3 tau  (semi-infinite limit with curvature)\n% Run: week11_topic2_sphere_release   (MATLAB R2016b or later)\n\nfprintf('=== 1. Series solution: centre concentration and remaining drug ===\\n');\nfprintf('  tau      c(0)/c0    m/m0 (series)   one-term (6/pi^2)e^(-pi^2 tau)\\n');\nfor tau = [0.01 0.03 0.05 0.1 0.2 0.3]\n    fprintf('  %5.2f    %.5f    %.5f        %.5f\\n', tau, theta_s(0, tau), remaining(tau), 6/pi^2*exp(-pi^2*tau));\nend\n\nfprintf('\\n=== 2. Check against a finite-volume solution (200 shells) ===\\n');\nfor tau = [0.03 0.1]\n    [cc, m] = finite_volume(tau, 200, 40000);\n    fprintf('  tau = %4.2f: centre FV = %.4f vs series %.4f; m/m0 FV = %.4f vs series %.4f\\n', ...\n        tau, cc, theta_s(0.5/200, tau), m, remaining(tau));\nend\n\nfprintf('\\n=== 3. Characteristic release times ===\\n');\nt50 = tau_for(0.5); t90 = tau_for(0.1);\nfprintf('  50%% released at tau = %.4f;  90%% released at tau = %.4f\\n', t50, t90);\nfprintf('  short-time check: 6 sqrt(tau/pi) - 3 tau at tau_50 = %.4f (should be 0.5)\\n', 6*sqrt(t50/pi) - 3*t50);\n\nfprintf('\\n=== 4. Case: release from hydrogel beads (illustrative diffusivities) ===\\n');\nnames = {'small drug, D = 5e-10 m^2/s', 'protein, D = 1e-11 m^2/s'};\nDs = [5e-10 1e-11];\nfor k = 1:2\n    fprintf('  %s\\n', names{k});\n    for Rmm = [0.1 0.5 1.0 2.0]\n        R = Rmm*1e-3;\n        fprintf('    R = %3.1f mm: t50 = %8.2f min, t90 = %8.1f min\\n', Rmm, t50*R^2/Ds(k)/60, t90*R^2/Ds(k)/60);\n    end\nend\nfprintf('  -> release time scales as R^2/D: halving the bead radius releases four times faster\\n');\n\n% ------------------------------------------------------------------ local functions\nfunction f = remaining(tau)\n    if tau <= 0, f = 1; return; end\n    n = 1:400;\n    f = 6/pi^2 * sum(exp(-(n*pi).^2*tau)./n.^2);\nend\n\nfunction s = theta_s(rho, tau)\n    if tau <= 0, s = 1; return; end\n    s = 0;\n    for n = 1:400\n        e = exp(-(n*pi)^2*tau);\n        if e < 1e-300, break; end\n        if rho < 1e-12, shape = n*pi; else, shape = sin(n*pi*rho)/rho; end\n        s = s + 2*(-1)^(n+1)/(n*pi)*shape*e;\n    end\nend\n\nfunction tau = tau_for(target)\n    lo = 1e-8; hi = 5;\n    for i = 1:200\n        mid = sqrt(lo*hi);\n        if remaining(mid) > target, lo = mid; else, hi = mid; end\n    end\n    tau = sqrt(lo*hi);\nend\n\nfunction [c0, m] = finite_volume(tauEnd, N, steps)\n    dr = 1/N; dt = tauEnd/steps;\n    i = 0:N-1;\n    vol = ((i+1).^3 - i.^3)*dr^3/3;\n    area = (i+1).^2*dr^2;\n    c = ones(1, N);\n    for s = 1:steps\n        flux = zeros(1, N);\n        flux(1:N-1) = -area(1:N-1).*(c(2:N) - c(1:N-1))/dr;\n        flux(N) = -area(N)*(0 - c(N))/(0.5*dr);\n        inflow = [0, flux(1:N-1)] - flux;\n        c = c + dt*inflow./vol;\n    end\n    c0 = c(1);\n    m = 3*sum(c.*vol);\nend\n",
    julia: "# Week 11 - Topic 2: Transient Diffusion in a Sphere - Drug Release from a Gel Bead\n# Lecture (Part 1):\n#   dc/dt = D (d2c/dr2 + (2/r) dc/dr),  c(R,t) = cs = 0 (perfect sink),  dc/dr(0,t) = 0,  c(r,0) = c0\n#   (c - c0)/(cs - c0) = 1 + (2R/(pi r)) sum_n (-1)^n/n sin(n pi r/R) exp(-n^2 pi^2 D t/R^2)\n#   centre (r -> 0, sin x/x -> 1):  (c(0,t) - c0)/(cs - c0) = 1 + 2 sum_n (-1)^n exp(-n^2 pi^2 tau)\n#   release rate   W(t) = 8 pi c0 D R sum_n exp(-n^2 pi^2 tau)\n#   remaining      m(t)/m0 = (6/pi^2) sum_n (1/n^2) exp(-n^2 pi^2 tau),   tau = D t / R^2\n#   long times (one term): m/m0 ~ (6/pi^2) exp(-pi^2 tau)  (the lecture writes ~ exp(-pi^2 tau))\n#   short times: released fraction ~ 6 sqrt(tau/pi) - 3 tau  (semi-infinite limit with curvature)\n# Run: julia week11_topic2_sphere_release.jl\n\nusing Printf\n\nremaining(tau; nterms=400) = tau <= 0 ? 1.0 : 6 / pi^2 * sum(exp(-(n * pi)^2 * tau) / n^2 for n in 1:nterms)\n\nfunction theta(rho, tau; nterms=400)\n    tau <= 0 && return 1.0\n    s = 0.0\n    for n in 1:nterms\n        e = exp(-(n * pi)^2 * tau)\n        e < 1e-300 && break\n        shape = rho < 1e-12 ? n * pi : sin(n * pi * rho) / rho\n        s += 2.0 * (isodd(n) ? 1.0 : -1.0) / (n * pi) * shape * e\n    end\n    return s\nend\n\nfunction tau_for(target)\n    lo, hi = 1e-8, 5.0\n    for _ in 1:200\n        mid = sqrt(lo * hi)\n        remaining(mid) > target ? (lo = mid) : (hi = mid)\n    end\n    return sqrt(lo * hi)\nend\n\nfunction finite_volume(tauEnd; N=200, steps=40000)\n    dr = 1 / N; dt = tauEnd / steps\n    vol = [((i + 1)^3 - i^3) * dr^3 / 3 for i in 0:N-1]\n    area = [(i + 1)^2 * dr^2 for i in 0:N-1]\n    c = ones(N); flux = zeros(N); nw = zeros(N)\n    for _ in 1:steps\n        for i in 1:N-1\n            flux[i] = -area[i] * (c[i+1] - c[i]) / dr\n        end\n        flux[N] = -area[N] * (0.0 - c[N]) / (0.5 * dr)\n        for i in 1:N\n            inflow = (i > 1 ? flux[i-1] : 0.0) - flux[i]\n            nw[i] = c[i] + dt * inflow / vol[i]\n        end\n        c .= nw\n    end\n    return c[1], 3 * sum(c .* vol)\nend\n\nprintln(\"=== 1. Series solution: centre concentration and remaining drug ===\")\nprintln(\"  tau      c(0)/c0    m/m0 (series)   one-term (6/pi^2)e^(-pi^2 tau)\")\nfor tau in (0.01, 0.03, 0.05, 0.1, 0.2, 0.3)\n    @printf(\"  %5.2f    %.5f    %.5f        %.5f\\n\", tau, theta(0.0, tau), remaining(tau), 6 / pi^2 * exp(-pi^2 * tau))\nend\n\nprintln(\"\\n=== 2. Check against a finite-volume solution (200 shells) ===\")\nfor tau in (0.03, 0.1)\n    cc, m = finite_volume(tau)\n    @printf(\"  tau = %4.2f: centre FV = %.4f vs series %.4f; m/m0 FV = %.4f vs series %.4f\\n\",\n            tau, cc, theta(0.5 / 200, tau), m, remaining(tau))\nend\n\nprintln(\"\\n=== 3. Characteristic release times ===\")\nt50, t90 = tau_for(0.5), tau_for(0.1)\n@printf(\"  50%% released at tau = %.4f;  90%% released at tau = %.4f\\n\", t50, t90)\n@printf(\"  short-time check: 6 sqrt(tau/pi) - 3 tau at tau_50 = %.4f (should be 0.5)\\n\", 6 * sqrt(t50 / pi) - 3 * t50)\n\nprintln(\"\\n=== 4. Case: release from hydrogel beads (illustrative diffusivities) ===\")\nfor (name, D) in ((\"small drug, D = 5e-10 m^2/s\", 5e-10), (\"protein, D = 1e-11 m^2/s\", 1e-11))\n    println(\"  \", name)\n    for Rmm in (0.1, 0.5, 1.0, 2.0)\n        R = Rmm * 1e-3\n        @printf(\"    R = %3.1f mm: t50 = %8.2f min, t90 = %8.1f min\\n\", Rmm, t50 * R^2 / D / 60, t90 * R^2 / D / 60)\n    end\nend\nprintln(\"  -> release time scales as R^2/D: halving the bead radius releases four times faster\")\n",
    cpp: "// Week 11 - Topic 2: Transient Diffusion in a Sphere - Drug Release from a Gel Bead\n// Lecture (Part 1):\n//   dc/dt = D (d2c/dr2 + (2/r) dc/dr),  c(R,t) = cs = 0 (perfect sink),  dc/dr(0,t) = 0,  c(r,0) = c0\n//   (c - c0)/(cs - c0) = 1 + (2R/(pi r)) sum_n (-1)^n/n sin(n pi r/R) exp(-n^2 pi^2 D t/R^2)\n//   centre (r -> 0, sin x/x -> 1):  (c(0,t) - c0)/(cs - c0) = 1 + 2 sum_n (-1)^n exp(-n^2 pi^2 tau)\n//   release rate   W(t) = 8 pi c0 D R sum_n exp(-n^2 pi^2 tau)\n//   remaining      m(t)/m0 = (6/pi^2) sum_n (1/n^2) exp(-n^2 pi^2 tau),   tau = D t / R^2\n//   long times (one term): m/m0 ~ (6/pi^2) exp(-pi^2 tau)  (the lecture writes ~ exp(-pi^2 tau))\n//   short times: released fraction ~ 6 sqrt(tau/pi) - 3 tau  (semi-infinite limit with curvature)\n// Build: g++ -O2 -std=c++17 week11_topic2_sphere_release.cpp -o topic2\n#include <cmath>\n#include <cstdio>\n#include <initializer_list>\n#include <utility>\n#include <vector>\n\nconst double PI = 3.14159265358979323846;\n\ndouble remainingFraction(double tau, int nterms = 400) {\n    if (tau <= 0) return 1.0;\n    double s = 0.0;\n    for (int n = 1; n <= nterms; ++n) s += std::exp(-std::pow(n * PI, 2) * tau) / (double(n) * n);\n    return 6.0 / (PI * PI) * s;\n}\n\ndouble theta(double rho, double tau, int nterms = 400) {\n    if (tau <= 0) return 1.0;\n    double s = 0.0;\n    for (int n = 1; n <= nterms; ++n) {\n        double e = std::exp(-std::pow(n * PI, 2) * tau);\n        if (e < 1e-300) break;\n        double shape = rho < 1e-12 ? n * PI : std::sin(n * PI * rho) / rho;\n        s += 2.0 * ((n % 2) ? 1.0 : -1.0) / (n * PI) * shape * e;\n    }\n    return s;\n}\n\ndouble tauFor(double remaining) {\n    double lo = 1e-8, hi = 5.0;\n    for (int i = 0; i < 200; ++i) {\n        double mid = std::sqrt(lo * hi);\n        if (remainingFraction(mid) > remaining) lo = mid; else hi = mid;\n    }\n    return std::sqrt(lo * hi);\n}\n\nstd::pair<double, double> finiteVolume(double tauEnd, int N = 200, int steps = 40000) {\n    double dr = 1.0 / N, dt = tauEnd / steps;\n    std::vector<double> vol(N), area(N), c(N, 1.0), flux(N), nw(N);\n    for (int i = 0; i < N; ++i) {\n        vol[i] = (std::pow(i + 1, 3) - std::pow(i, 3)) * dr * dr * dr / 3.0;\n        area[i] = std::pow(i + 1, 2) * dr * dr;\n    }\n    for (int s = 0; s < steps; ++s) {\n        for (int i = 0; i < N - 1; ++i) flux[i] = -area[i] * (c[i + 1] - c[i]) / dr;\n        flux[N - 1] = -area[N - 1] * (0.0 - c[N - 1]) / (0.5 * dr);\n        for (int i = 0; i < N; ++i) {\n            double inflow = (i > 0 ? flux[i - 1] : 0.0) - flux[i];\n            nw[i] = c[i] + dt * inflow / vol[i];\n        }\n        c = nw;\n    }\n    double m = 0.0;\n    for (int i = 0; i < N; ++i) m += c[i] * vol[i];\n    return {c[0], 3.0 * m};\n}\n\nint main() {\n    std::printf(\"=== 1. Series solution: centre concentration and remaining drug ===\\n\");\n    std::printf(\"  tau      c(0)/c0    m/m0 (series)   one-term (6/pi^2)e^(-pi^2 tau)\\n\");\n    for (double tau : {0.01, 0.03, 0.05, 0.1, 0.2, 0.3})\n        std::printf(\"  %5.2f    %.5f    %.5f        %.5f\\n\", tau, theta(0.0, tau), remainingFraction(tau),\n                    6 / (PI * PI) * std::exp(-PI * PI * tau));\n\n    std::printf(\"\\n=== 2. Check against a finite-volume solution (200 shells) ===\\n\");\n    for (double tau : {0.03, 0.1}) {\n        auto fv = finiteVolume(tau);\n        std::printf(\"  tau = %4.2f: centre FV = %.4f vs series %.4f; m/m0 FV = %.4f vs series %.4f\\n\",\n                    tau, fv.first, theta(0.5 / 200, tau), fv.second, remainingFraction(tau));\n    }\n\n    std::printf(\"\\n=== 3. Characteristic release times ===\\n\");\n    double t50 = tauFor(0.5), t90 = tauFor(0.1);\n    std::printf(\"  50%% released at tau = %.4f;  90%% released at tau = %.4f\\n\", t50, t90);\n    std::printf(\"  short-time check: 6 sqrt(tau/pi) - 3 tau at tau_50 = %.4f (should be 0.5)\\n\",\n                6 * std::sqrt(t50 / PI) - 3 * t50);\n\n    std::printf(\"\\n=== 4. Case: release from hydrogel beads (illustrative diffusivities) ===\\n\");\n    const char* names[2] = {\"small drug, D = 5e-10 m^2/s\", \"protein, D = 1e-11 m^2/s\"};\n    double Ds[2] = {5e-10, 1e-11};\n    for (int k = 0; k < 2; ++k) {\n        std::printf(\"  %s\\n\", names[k]);\n        for (double Rmm : {0.1, 0.5, 1.0, 2.0}) {\n            double R = Rmm * 1e-3;\n            std::printf(\"    R = %3.1f mm: t50 = %8.2f min, t90 = %8.1f min\\n\", Rmm,\n                        t50 * R * R / Ds[k] / 60, t90 * R * R / Ds[k] / 60);\n        }\n    }\n    std::printf(\"  -> release time scales as R^2/D: halving the bead radius releases four times faster\\n\");\n    return 0;\n}\n",
  },
  topic3: {
    title: "Sturm-Liouville & Bessel: Heated Wire",
    python: "# Week 11 - Topic 3: Sturm-Liouville Eigenfunctions in a Cylinder - Bessel Functions and the Heated Wire\n# Lecture (Part 2):\n#   * Sturm-Liouville operator L = (1/w) [d/dx (p d/dx) + q]; self-adjoint with homogeneous BCs\n#     -> real eigenvalues, orthogonal eigenfunctions <u_m, u_n> = int u_m u_n w dx = 0 (m != n)\n#   * cylinder (w = r, p = r, q = 0): (1/r)(r F')' = -lambda^2 F  ->  F = a J0(lambda r)  (Y0 diverges at r = 0)\n#     Type 1  F(1) = 0          : J0(lambda) = 0           lambda = 2.405, 5.520, 8.654, ...\n#     Type 2  F'(1) = 0         : J1(lambda) = 0           lambda = 0, 3.832, 7.016, 10.173, ...\n#     Type 3  F'(1) + Bi F(1) = 0: lambda J1(lambda) = Bi J0(lambda)\n#     normalisation  int_0^1 J0(lambda r)^2 r dr = [J0(lambda)^2 + J1(lambda)^2]/2\n#   * Ex 1 (lecture): electrically heated wire, dTheta/dt = (1/r)(r Theta_r)_r + 1,\n#     Theta(r,0) = 0, Theta_r(0) = 0, Theta_r(1) + Bi Theta(1) = 0  (finite Fourier transform):\n#     Theta = 2 sum_n J1(l_n) J0(l_n r) / (l_n^3 J0(l_n)^2 (1 + (Bi/l_n)^2)) (1 - exp(-l_n^2 t))\n#     steady state Theta_ss = 1/(2 Bi) + (1 - r^2)/4\n#   Dimensionless: Theta = k (T - T_inf)/(q''' R^2), t = alpha t/R^2, Bi = h R/k.\n# Bessel functions are computed from the integral J_n(x) = (1/pi) int_0^pi cos(n s - x sin s) ds\n# with the trapezoidal rule, which converges exponentially for this periodic integrand.\n\nimport math\n\n\ndef besselj(n, x, m=200):\n    h = math.pi / m\n    s = 0.5 * (math.cos(0.0) + math.cos(n * math.pi - x * math.sin(math.pi)))\n    for k in range(1, m):\n        u = k * h\n        s += math.cos(n * u - x * math.sin(u))\n    return s * h / math.pi\n\n\ndef roots(f, xmax=20.0, dx=0.01):\n    out, x = [], 1e-9\n    fx = f(x)\n    while x < xmax:\n        x2 = x + dx\n        f2 = f(x2)\n        if fx * f2 < 0:\n            a, b = x, x2\n            for _ in range(80):\n                c = 0.5 * (a + b)\n                if f(a) * f(c) <= 0:\n                    b = c\n                else:\n                    a = c\n            out.append(0.5 * (a + b))\n        x, fx = x2, f2\n    return out\n\n\ndef eigenvalues(bc, Bi=1.0, n=4):\n    if bc == 1:\n        return roots(lambda x: besselj(0, x))[:n]\n    if bc == 2:\n        return [0.0] + roots(lambda x: besselj(1, x))[: n - 1]\n    return roots(lambda x: x * besselj(1, x) - Bi * besselj(0, x))[:n]\n\n\ndef simpson(f, a, b, n=400):\n    h = (b - a) / n\n    s = f(a) + f(b)\n    for i in range(1, n):\n        s += (4 if i % 2 else 2) * f(a + i * h)\n    return s * h / 3\n\n\ndef wire_series(r, t, Bi, lams):\n    s = 0.0\n    for l in lams:\n        J0l, J1l = besselj(0, l), besselj(1, l)\n        s += 2 * J1l * besselj(0, l * r) / (l ** 3 * J0l ** 2 * (1 + (Bi / l) ** 2)) * (1 - math.exp(-l * l * t))\n    return s\n\n\ndef wire_fd(t_end, Bi, N=60):\n    \"\"\"explicit finite volume on r in [0,1] with the Robin condition at r = 1\"\"\"\n    dr = 1.0 / N\n    steps = int(t_end / (0.2 * dr * dr)) + 1      # explicit stability: dt < dr^2/4\n    dt = t_end / steps\n    rc = [(i + 0.5) * dr for i in range(N)]\n    th = [0.0] * N\n    for _ in range(steps):\n        new = th[:]\n        for i in range(N):\n            rw, re = i * dr, (i + 1) * dr\n            fw = rw * (th[i] - th[i - 1]) / dr if i > 0 else 0.0\n            if i < N - 1:\n                fe = re * (th[i + 1] - th[i]) / dr\n            else:  # surface value from Robin: (Ts - th)/(dr/2) = -Bi Ts\n                Ts = th[i] / (1 + Bi * dr / 2)\n                fe = re * (Ts - th[i]) / (dr / 2)\n            new[i] = th[i] + dt * ((fe - fw) / (rc[i] * dr) + 1.0)\n        th = new\n    return rc, th\n\n\nif __name__ == \"__main__\":\n    print(\"=== 1. Eigenvalues for the three boundary-condition types ===\")\n    fmt = lambda v: \"[\" + \", \".join(f\"{x:.4f}\" for x in v) + \"]\"\n    print(\"  Type 1 (J0 = 0):\", fmt(eigenvalues(1)))\n    print(\"  Type 2 (J1 = 0):\", fmt(eigenvalues(2)))\n    for Bi in (0.1, 1.0, 10.0):\n        print(f\"  Type 3, Bi = {Bi:4.1f}:\", fmt(eigenvalues(3, Bi)))\n\n    print(\"\\n=== 2. Orthogonality (weight w = r) and normalisation ===\")\n    lam = eigenvalues(1)\n    for i in range(3):\n        row = []\n        for j in range(3):\n            row.append(simpson(lambda r: besselj(0, lam[i] * r) * besselj(0, lam[j] * r) * r, 0, 1))\n        print(\"  \", \" \".join(f\"{v:+.6f}\" for v in row))\n    l1 = lam[0]\n    print(f\"  int J0(l1 r)^2 r dr = {simpson(lambda r: besselj(0, l1*r)**2*r, 0, 1):.6f}, \"\n          f\"formula (J0^2 + J1^2)/2 = {(besselj(0,l1)**2 + besselj(1,l1)**2)/2:.6f}\")\n\n    print(\"\\n=== 3. Heated wire (Ex 1): series vs finite volume ===\")\n    Bi = 1.0\n    lams = eigenvalues(3, Bi, 30)\n    for t in (0.05, 0.2, 1.0):\n        rc, th = wire_fd(t, Bi)\n        print(f\"  t = {t:4.2f}: centre series = {wire_series(0.0, t, Bi, lams):.5f}, FV = {th[0]:.5f};\"\n              f\"  surface series = {wire_series(1.0, t, Bi, lams):.5f}\")\n    print(f\"  steady state 1/(2Bi) + 1/4 = {1/(2*Bi)+0.25:.5f}; series at t = 10: {wire_series(0, 10, Bi, lams):.5f}\")\n    print(f\"  time to reach 95% of the steady centre value: \", end=\"\")\n    target = 0.95 * (1 / (2 * Bi) + 0.25)\n    lo, hi = 0.0, 10.0\n    for _ in range(60):\n        mid = 0.5 * (lo + hi)\n        if wire_series(0, mid, Bi, lams) < target:\n            lo = mid\n        else:\n            hi = mid\n    print(f\"t = {mid:.3f}  (one-term estimate 3/lambda1^2 = {3/lams[0]**2:.3f})\")\n\n    print(\"\\n=== 4. Case: thin Pt wire, R = 25 um, in still air ===\")\n    k, alpha, h, q = 71.6, 2.5e-5, 300.0, 1e9      # W/m/K, m^2/s, W/m^2/K, W/m^3 (illustrative)\n    R = 25e-6\n    Bi = h * R / k\n    print(f\"  Bi = hR/k = {Bi:.2e} -> nearly uniform temperature (lumped), lambda1 = {eigenvalues(3, Bi, 1)[0]:.4f}\")\n    print(f\"  steady rise T - T_inf = q R / (2 h) = {q*R/(2*h):.1f} K; time constant R^2/(alpha lambda1^2) = \"\n          f\"{R*R/(alpha*eigenvalues(3, Bi, 1)[0]**2)*1e3:.2f} ms (lumped rho c R/(2h))\")\n",
    matlab: "% Week 11 - Topic 3: Sturm-Liouville Eigenfunctions in a Cylinder - Bessel Functions and the Heated Wire\n% Lecture (Part 2):\n%   * Sturm-Liouville operator L = (1/w) [d/dx (p d/dx) + q]; self-adjoint with homogeneous BCs\n%     -> real eigenvalues, orthogonal eigenfunctions <u_m, u_n> = int u_m u_n w dx = 0 (m != n)\n%   * cylinder (w = r, p = r, q = 0): (1/r)(r F')' = -lambda^2 F  ->  F = a J0(lambda r)  (Y0 diverges at r = 0)\n%     Type 1  F(1) = 0          : J0(lambda) = 0           lambda = 2.405, 5.520, 8.654, ...\n%     Type 2  F'(1) = 0         : J1(lambda) = 0           lambda = 0, 3.832, 7.016, 10.173, ...\n%     Type 3  F'(1) + Bi F(1) = 0: lambda J1(lambda) = Bi J0(lambda)\n%     normalisation  int_0^1 J0(lambda r)^2 r dr = [J0(lambda)^2 + J1(lambda)^2]/2\n%   * Ex 1 (lecture): electrically heated wire, dTheta/dt = (1/r)(r Theta_r)_r + 1,\n%     Theta(r,0) = 0, Theta_r(0) = 0, Theta_r(1) + Bi Theta(1) = 0  (finite Fourier transform):\n%     Theta = 2 sum_n J1(l_n) J0(l_n r) / (l_n^3 J0(l_n)^2 (1 + (Bi/l_n)^2)) (1 - exp(-l_n^2 t))\n%     steady state Theta_ss = 1/(2 Bi) + (1 - r^2)/4\n%   Dimensionless: Theta = k (T - T_inf)/(q''' R^2), t = alpha t/R^2, Bi = h R/k.\n% MATLAB's built-in besselj is used; fzero brackets each root found on a fine grid.\n% Run: week11_topic3_bessel_cylinder   (MATLAB R2016b or later)\n\nfprintf('=== 1. Eigenvalues for the three boundary-condition types ===\\n');\nfprintf('  Type 1 (J0 = 0): %s\\n', fmtv(eigenvalues(1, 0, 4)));\nfprintf('  Type 2 (J1 = 0): %s\\n', fmtv(eigenvalues(2, 0, 4)));\nfor Bi = [0.1 1.0 10.0]\n    fprintf('  Type 3, Bi = %4.1f: %s\\n', Bi, fmtv(eigenvalues(3, Bi, 4)));\nend\n\nfprintf('\\n=== 2. Orthogonality (weight w = r) and normalisation ===\\n');\nlam = eigenvalues(1, 0, 4);\nfor i = 1:3\n    fprintf('  ');\n    for j = 1:3\n        fprintf(' %+.6f', integral(@(r) besselj(0, lam(i)*r).*besselj(0, lam(j)*r).*r, 0, 1));\n    end\n    fprintf('\\n');\nend\nl1 = lam(1);\nfprintf('  int J0(l1 r)^2 r dr = %.6f, formula (J0^2 + J1^2)/2 = %.6f\\n', ...\n    integral(@(r) besselj(0, l1*r).^2.*r, 0, 1), (besselj(0, l1)^2 + besselj(1, l1)^2)/2);\n\nfprintf('\\n=== 3. Heated wire (Ex 1): series vs finite volume ===\\n');\nBi = 1.0;\nlams = eigenvalues(3, Bi, 30);\nfor t = [0.05 0.2 1.0]\n    th = wire_fd(t, Bi, 60);\n    fprintf('  t = %4.2f: centre series = %.5f, FV = %.5f;  surface series = %.5f\\n', ...\n        t, wire_series(0, t, Bi, lams), th(1), wire_series(1, t, Bi, lams));\nend\nfprintf('  steady state 1/(2Bi) + 1/4 = %.5f; series at t = 10: %.5f\\n', 1/(2*Bi) + 0.25, wire_series(0, 10, Bi, lams));\ntarget = 0.95*(1/(2*Bi) + 0.25); lo = 0; hi = 10;\nfor k = 1:60\n    mid = 0.5*(lo + hi);\n    if wire_series(0, mid, Bi, lams) < target, lo = mid; else, hi = mid; end\nend\nfprintf('  time to reach 95%% of the steady centre value: t = %.3f  (one-term estimate 3/lambda1^2 = %.3f)\\n', mid, 3/lams(1)^2);\n\nfprintf('\\n=== 4. Case: thin Pt wire, R = 25 um, in still air ===\\n');\nk = 71.6; alpha = 2.5e-5; h = 300; q = 1e9; R = 25e-6;\nBiw = h*R/k; l1w = eigenvalues(3, Biw, 1);\nfprintf('  Bi = hR/k = %.2e -> nearly uniform temperature (lumped), lambda1 = %.4f\\n', Biw, l1w);\nfprintf('  steady rise T - T_inf = q R / (2 h) = %.1f K; time constant R^2/(alpha lambda1^2) = %.2f ms (lumped rho c R/(2h))\\n', ...\n    q*R/(2*h), R^2/(alpha*l1w^2)*1e3);\n\n% ------------------------------------------------------------------ local functions\nfunction s = fmtv(v)\n    s = ['[' strjoin(arrayfun(@(x) sprintf('%.4f', x), v, 'UniformOutput', false), ', ') ']'];\nend\n\nfunction lam = eigenvalues(bc, Bi, n)\n    switch bc\n        case 1, f = @(x) besselj(0, x);\n        case 2, f = @(x) besselj(1, x);\n        otherwise, f = @(x) x.*besselj(1, x) - Bi*besselj(0, x);\n    end\n    x = 1e-9:0.01:20; fx = f(x);\n    idx = find(fx(1:end-1).*fx(2:end) < 0);\n    lam = arrayfun(@(i) fzero(f, [x(i) x(i+1)]), idx);\n    if bc == 2, lam = [0 lam]; end\n    lam = lam(1:min(n, numel(lam)));\nend\n\nfunction s = wire_series(r, t, Bi, lams)\n    s = 0;\n    for l = lams\n        s = s + 2*besselj(1, l)*besselj(0, l*r)/(l^3*besselj(0, l)^2*(1 + (Bi/l)^2))*(1 - exp(-l^2*t));\n    end\nend\n\nfunction th = wire_fd(tEnd, Bi, N)\n    dr = 1/N; steps = floor(tEnd/(0.2*dr^2)) + 1; dt = tEnd/steps;\n    rw = (0:N-1)*dr; re = (1:N)*dr; rc = ((0:N-1) + 0.5)*dr;\n    th = zeros(1, N);\n    for s = 1:steps\n        fw = [0, rw(2:N).*(th(2:N) - th(1:N-1))/dr];\n        Ts = th(N)/(1 + Bi*dr/2);\n        fe = [re(1:N-1).*(th(2:N) - th(1:N-1))/dr, re(N)*(Ts - th(N))/(dr/2)];\n        th = th + dt*((fe - fw)./(rc*dr) + 1);\n    end\nend\n",
    julia: "# Week 11 - Topic 3: Sturm-Liouville Eigenfunctions in a Cylinder - Bessel Functions and the Heated Wire\n# Lecture (Part 2):\n#   * Sturm-Liouville operator L = (1/w) [d/dx (p d/dx) + q]; self-adjoint with homogeneous BCs\n#     -> real eigenvalues, orthogonal eigenfunctions <u_m, u_n> = int u_m u_n w dx = 0 (m != n)\n#   * cylinder (w = r, p = r, q = 0): (1/r)(r F')' = -lambda^2 F  ->  F = a J0(lambda r)  (Y0 diverges at r = 0)\n#     Type 1  F(1) = 0          : J0(lambda) = 0           lambda = 2.405, 5.520, 8.654, ...\n#     Type 2  F'(1) = 0         : J1(lambda) = 0           lambda = 0, 3.832, 7.016, 10.173, ...\n#     Type 3  F'(1) + Bi F(1) = 0: lambda J1(lambda) = Bi J0(lambda)\n#     normalisation  int_0^1 J0(lambda r)^2 r dr = [J0(lambda)^2 + J1(lambda)^2]/2\n#   * Ex 1 (lecture): electrically heated wire, dTheta/dt = (1/r)(r Theta_r)_r + 1,\n#     Theta(r,0) = 0, Theta_r(0) = 0, Theta_r(1) + Bi Theta(1) = 0  (finite Fourier transform):\n#     Theta = 2 sum_n J1(l_n) J0(l_n r) / (l_n^3 J0(l_n)^2 (1 + (Bi/l_n)^2)) (1 - exp(-l_n^2 t))\n#     steady state Theta_ss = 1/(2 Bi) + (1 - r^2)/4\n#   Dimensionless: Theta = k (T - T_inf)/(q''' R^2), t = alpha t/R^2, Bi = h R/k.\n# Bessel functions from J_n(x) = (1/pi) int_0^pi cos(n s - x sin s) ds (trapezoidal rule), so no\n# package is needed (SpecialFunctions.besselj would give the same numbers).\n# Run: julia week11_topic3_bessel_cylinder.jl\n\nusing Printf\n\nfunction besselj(n, x; m=200)\n    h = pi / m\n    s = 0.5 * (cos(0.0) + cos(n * pi - x * sin(pi)))\n    for k in 1:m-1\n        u = k * h\n        s += cos(n * u - x * sin(u))\n    end\n    return s * h / pi\nend\n\nfunction roots(f; xmax=20.0, dx=0.01)\n    out = Float64[]\n    x = 1e-9; fx = f(x)\n    while x < xmax\n        x2 = x + dx; f2 = f(x2)\n        if fx * f2 < 0\n            a, b = x, x2\n            for _ in 1:80\n                c = 0.5 * (a + b)\n                f(a) * f(c) <= 0 ? (b = c) : (a = c)\n            end\n            push!(out, 0.5 * (a + b))\n        end\n        x, fx = x2, f2\n    end\n    return out\nend\n\nfunction eigenvalues(bc; Bi=1.0, n=4)\n    r = bc == 1 ? roots(x -> besselj(0, x)) :\n        bc == 2 ? vcat(0.0, roots(x -> besselj(1, x))) :\n                  roots(x -> x * besselj(1, x) - Bi * besselj(0, x))\n    return r[1:min(n, length(r))]\nend\n\nfunction simpson(f, a, b; n=400)\n    h = (b - a) / n\n    s = f(a) + f(b)\n    for i in 1:n-1\n        s += (isodd(i) ? 4 : 2) * f(a + i * h)\n    end\n    return s * h / 3\nend\n\nwire_series(r, t, Bi, lams) = sum(2 * besselj(1, l) * besselj(0, l * r) /\n    (l^3 * besselj(0, l)^2 * (1 + (Bi / l)^2)) * (1 - exp(-l^2 * t)) for l in lams)\n\nfunction wire_fd(tEnd, Bi; N=60)\n    dr = 1 / N\n    steps = floor(Int, tEnd / (0.2 * dr^2)) + 1\n    dt = tEnd / steps\n    th = zeros(N); nw = zeros(N)\n    for _ in 1:steps\n        for i in 1:N\n            rw, re, rc = (i - 1) * dr, i * dr, (i - 0.5) * dr\n            fw = i > 1 ? rw * (th[i] - th[i-1]) / dr : 0.0\n            if i < N\n                fe = re * (th[i+1] - th[i]) / dr\n            else\n                Ts = th[i] / (1 + Bi * dr / 2)\n                fe = re * (Ts - th[i]) / (dr / 2)\n            end\n            nw[i] = th[i] + dt * ((fe - fw) / (rc * dr) + 1.0)\n        end\n        th .= nw\n    end\n    return th\nend\n\nfmtv(v) = \"[\" * join([@sprintf(\"%.4f\", x) for x in v], \", \") * \"]\"\n\nprintln(\"=== 1. Eigenvalues for the three boundary-condition types ===\")\nprintln(\"  Type 1 (J0 = 0): \", fmtv(eigenvalues(1)))\nprintln(\"  Type 2 (J1 = 0): \", fmtv(eigenvalues(2)))\nfor Bi in (0.1, 1.0, 10.0)\n    println(@sprintf(\"  Type 3, Bi = %4.1f: \", Bi), fmtv(eigenvalues(3; Bi=Bi)))\nend\n\nprintln(\"\\n=== 2. Orthogonality (weight w = r) and normalisation ===\")\nlam = eigenvalues(1)\nfor i in 1:3\n    print(\"  \")\n    for j in 1:3\n        @printf(\" %+.6f\", simpson(r -> besselj(0, lam[i] * r) * besselj(0, lam[j] * r) * r, 0, 1))\n    end\n    println()\nend\nl1 = lam[1]\n@printf(\"  int J0(l1 r)^2 r dr = %.6f, formula (J0^2 + J1^2)/2 = %.6f\\n\",\n        simpson(r -> besselj(0, l1 * r)^2 * r, 0, 1), (besselj(0, l1)^2 + besselj(1, l1)^2) / 2)\n\nprintln(\"\\n=== 3. Heated wire (Ex 1): series vs finite volume ===\")\nBi = 1.0\nlams = eigenvalues(3; Bi=Bi, n=30)\nfor t in (0.05, 0.2, 1.0)\n    th = wire_fd(t, Bi)\n    @printf(\"  t = %4.2f: centre series = %.5f, FV = %.5f;  surface series = %.5f\\n\",\n            t, wire_series(0.0, t, Bi, lams), th[1], wire_series(1.0, t, Bi, lams))\nend\n@printf(\"  steady state 1/(2Bi) + 1/4 = %.5f; series at t = 10: %.5f\\n\", 1 / (2Bi) + 0.25, wire_series(0, 10, Bi, lams))\nlet target = 0.95 * (1 / (2Bi) + 0.25), lo = 0.0, hi = 10.0, mid = 0.0\n    for _ in 1:60\n        mid = 0.5 * (lo + hi)\n        wire_series(0, mid, Bi, lams) < target ? (lo = mid) : (hi = mid)\n    end\n    @printf(\"  time to reach 95%% of the steady centre value: t = %.3f  (one-term estimate 3/lambda1^2 = %.3f)\\n\", mid, 3 / lams[1]^2)\nend\n\nprintln(\"\\n=== 4. Case: thin Pt wire, R = 25 um, in still air ===\")\nk, alpha, h, q, R = 71.6, 2.5e-5, 300.0, 1e9, 25e-6\nBiw = h * R / k\nl1w = eigenvalues(3; Bi=Biw, n=1)[1]\n@printf(\"  Bi = hR/k = %.2e -> nearly uniform temperature (lumped), lambda1 = %.4f\\n\", Biw, l1w)\n@printf(\"  steady rise T - T_inf = q R / (2 h) = %.1f K; time constant R^2/(alpha lambda1^2) = %.2f ms (lumped rho c R/(2h))\\n\",\n        q * R / (2h), R^2 / (alpha * l1w^2) * 1e3)\n",
    cpp: "// Week 11 - Topic 3: Sturm-Liouville Eigenfunctions in a Cylinder - Bessel Functions and the Heated Wire\n// Lecture (Part 2):\n//   * Sturm-Liouville operator L = (1/w) [d/dx (p d/dx) + q]; self-adjoint with homogeneous BCs\n//     -> real eigenvalues, orthogonal eigenfunctions <u_m, u_n> = int u_m u_n w dx = 0 (m != n)\n//   * cylinder (w = r, p = r, q = 0): (1/r)(r F')' = -lambda^2 F  ->  F = a J0(lambda r)  (Y0 diverges at r = 0)\n//     Type 1  F(1) = 0          : J0(lambda) = 0           lambda = 2.405, 5.520, 8.654, ...\n//     Type 2  F'(1) = 0         : J1(lambda) = 0           lambda = 0, 3.832, 7.016, 10.173, ...\n//     Type 3  F'(1) + Bi F(1) = 0: lambda J1(lambda) = Bi J0(lambda)\n//     normalisation  int_0^1 J0(lambda r)^2 r dr = [J0(lambda)^2 + J1(lambda)^2]/2\n//   * Ex 1 (lecture): electrically heated wire, dTheta/dt = (1/r)(r Theta_r)_r + 1,\n//     Theta(r,0) = 0, Theta_r(0) = 0, Theta_r(1) + Bi Theta(1) = 0  (finite Fourier transform):\n//     Theta = 2 sum_n J1(l_n) J0(l_n r) / (l_n^3 J0(l_n)^2 (1 + (Bi/l_n)^2)) (1 - exp(-l_n^2 t))\n//     steady state Theta_ss = 1/(2 Bi) + (1 - r^2)/4\n//   Dimensionless: Theta = k (T - T_inf)/(q''' R^2), t = alpha t/R^2, Bi = h R/k.\n// Bessel functions from J_n(x) = (1/pi) int_0^pi cos(n s - x sin s) ds (trapezoidal rule).\n// Build: g++ -O2 -std=c++17 week11_topic3_bessel_cylinder.cpp -o topic3\n#include <cmath>\n#include <cstdio>\n#include <functional>\n#include <initializer_list>\n#include <vector>\n\nconst double PI = 3.14159265358979323846;\n\ndouble besselj(int n, double x, int m = 200) {\n    double h = PI / m;\n    double s = 0.5 * (std::cos(0.0) + std::cos(n * PI - x * std::sin(PI)));\n    for (int k = 1; k < m; ++k) {\n        double u = k * h;\n        s += std::cos(n * u - x * std::sin(u));\n    }\n    return s * h / PI;\n}\n\nstd::vector<double> roots(const std::function<double(double)>& f, double xmax = 20.0, double dx = 0.01) {\n    std::vector<double> out;\n    double x = 1e-9, fx = f(x);\n    while (x < xmax) {\n        double x2 = x + dx, f2 = f(x2);\n        if (fx * f2 < 0) {\n            double a = x, b = x2;\n            for (int i = 0; i < 80; ++i) {\n                double c = 0.5 * (a + b);\n                if (f(a) * f(c) <= 0) b = c; else a = c;\n            }\n            out.push_back(0.5 * (a + b));\n        }\n        x = x2; fx = f2;\n    }\n    return out;\n}\n\nstd::vector<double> eigenvalues(int bc, double Bi = 1.0, size_t n = 4) {\n    std::vector<double> r;\n    if (bc == 1) r = roots([](double x) { return besselj(0, x); });\n    else if (bc == 2) { r = roots([](double x) { return besselj(1, x); }); r.insert(r.begin(), 0.0); }\n    else r = roots([Bi](double x) { return x * besselj(1, x) - Bi * besselj(0, x); });\n    if (r.size() > n) r.resize(n);\n    return r;\n}\n\ndouble simpson(const std::function<double(double)>& f, double a, double b, int n = 400) {\n    double h = (b - a) / n, s = f(a) + f(b);\n    for (int i = 1; i < n; ++i) s += (i % 2 ? 4 : 2) * f(a + i * h);\n    return s * h / 3;\n}\n\ndouble wireSeries(double r, double t, double Bi, const std::vector<double>& lams) {\n    double s = 0.0;\n    for (double l : lams) {\n        double J0l = besselj(0, l), J1l = besselj(1, l);\n        s += 2 * J1l * besselj(0, l * r) / (l * l * l * J0l * J0l * (1 + (Bi / l) * (Bi / l))) * (1 - std::exp(-l * l * t));\n    }\n    return s;\n}\n\nstd::vector<double> wireFD(double tEnd, double Bi, int N = 60) {\n    double dr = 1.0 / N;\n    int steps = int(tEnd / (0.2 * dr * dr)) + 1;\n    double dt = tEnd / steps;\n    std::vector<double> th(N, 0.0), nw(N);\n    for (int s = 0; s < steps; ++s) {\n        for (int i = 0; i < N; ++i) {\n            double rw = i * dr, re = (i + 1) * dr, rc = (i + 0.5) * dr;\n            double fw = i > 0 ? rw * (th[i] - th[i - 1]) / dr : 0.0, fe;\n            if (i < N - 1) fe = re * (th[i + 1] - th[i]) / dr;\n            else { double Ts = th[i] / (1 + Bi * dr / 2); fe = re * (Ts - th[i]) / (dr / 2); }\n            nw[i] = th[i] + dt * ((fe - fw) / (rc * dr) + 1.0);\n        }\n        th = nw;\n    }\n    return th;\n}\n\nint main() {\n    auto pr = [](const char* lab, const std::vector<double>& v) {\n        std::printf(\"%s [\", lab);\n        for (size_t i = 0; i < v.size(); ++i) std::printf(\"%s%.4f\", i ? \", \" : \"\", v[i]);\n        std::printf(\"]\\n\");\n    };\n    std::printf(\"=== 1. Eigenvalues for the three boundary-condition types ===\\n\");\n    pr(\"  Type 1 (J0 = 0):\", eigenvalues(1));\n    pr(\"  Type 2 (J1 = 0):\", eigenvalues(2));\n    for (double Bi : {0.1, 1.0, 10.0}) {\n        char lab[64];\n        std::snprintf(lab, sizeof lab, \"  Type 3, Bi = %4.1f:\", Bi);\n        pr(lab, eigenvalues(3, Bi));\n    }\n\n    std::printf(\"\\n=== 2. Orthogonality (weight w = r) and normalisation ===\\n\");\n    std::vector<double> lam = eigenvalues(1);\n    for (int i = 0; i < 3; ++i) {\n        std::printf(\"  \");\n        for (int j = 0; j < 3; ++j)\n            std::printf(\" %+.6f\", simpson([&](double r) { return besselj(0, lam[i] * r) * besselj(0, lam[j] * r) * r; }, 0, 1));\n        std::printf(\"\\n\");\n    }\n    double l1 = lam[0];\n    std::printf(\"  int J0(l1 r)^2 r dr = %.6f, formula (J0^2 + J1^2)/2 = %.6f\\n\",\n                simpson([&](double r) { return std::pow(besselj(0, l1 * r), 2) * r; }, 0, 1),\n                (std::pow(besselj(0, l1), 2) + std::pow(besselj(1, l1), 2)) / 2);\n\n    std::printf(\"\\n=== 3. Heated wire (Ex 1): series vs finite volume ===\\n\");\n    double Bi = 1.0;\n    std::vector<double> lams = eigenvalues(3, Bi, 30);\n    for (double t : {0.05, 0.2, 1.0}) {\n        std::vector<double> th = wireFD(t, Bi);\n        std::printf(\"  t = %4.2f: centre series = %.5f, FV = %.5f;  surface series = %.5f\\n\",\n                    t, wireSeries(0.0, t, Bi, lams), th[0], wireSeries(1.0, t, Bi, lams));\n    }\n    std::printf(\"  steady state 1/(2Bi) + 1/4 = %.5f; series at t = 10: %.5f\\n\", 1 / (2 * Bi) + 0.25, wireSeries(0, 10, Bi, lams));\n    double target = 0.95 * (1 / (2 * Bi) + 0.25), lo = 0.0, hi = 10.0, mid = 0.0;\n    for (int i = 0; i < 60; ++i) {\n        mid = 0.5 * (lo + hi);\n        if (wireSeries(0, mid, Bi, lams) < target) lo = mid; else hi = mid;\n    }\n    std::printf(\"  time to reach 95%% of the steady centre value: t = %.3f  (one-term estimate 3/lambda1^2 = %.3f)\\n\",\n                mid, 3 / (lams[0] * lams[0]));\n\n    std::printf(\"\\n=== 4. Case: thin Pt wire, R = 25 um, in still air ===\\n\");\n    double k = 71.6, alpha = 2.5e-5, h = 300.0, q = 1e9, R = 25e-6;\n    double Biw = h * R / k, l1w = eigenvalues(3, Biw, 1)[0];\n    std::printf(\"  Bi = hR/k = %.2e -> nearly uniform temperature (lumped), lambda1 = %.4f\\n\", Biw, l1w);\n    std::printf(\"  steady rise T - T_inf = q R / (2 h) = %.1f K; time constant R^2/(alpha lambda1^2) = %.2f ms (lumped rho c R/(2h))\\n\",\n                q * R / (2 * h), R * R / (alpha * l1w * l1w) * 1e3);\n    return 0;\n}\n",
  },
  topic4: {
    title: "Sphere with Reaction & Legendre (Maxwell)",
    python: "# Week 11 - Topic 4: Spherical Coordinates - Reaction in a Catalyst Pellet and Legendre Polynomials\n# Lecture (Part 3):\n#   * radial problem (w = r^2, p = r^2): (1/r^2)(r^2 F')' = -lambda^2 F -> F = sin(lambda r)/r (spherical Bessel j0)\n#       Type 1 F(1) = 0: lambda_n = n pi;  Type 2 F'(1) = 0: lambda = tan(lambda);\n#       Type 3 F'(1) + A F(1) = 0: lambda = (1 - A) tan(lambda)\n#   * Ex 1, steady first-order reaction in a sphere, Da = k R^2/D (= phi^2, Thiele modulus squared):\n#       (1/r^2)(r^2 Theta')' - Da Theta = 0, Theta'(0) = 0, Theta(1) = 1\n#       Theta = sinh(sqrt(Da) r)/(r sinh(sqrt(Da)))     (modified spherical Bessel i0)\n#       effectiveness factor eta = 3 (phi coth phi - 1)/phi^2\n#   * Ex 2, transient start-up, Theta(r,0) = 0 (finite Fourier transform with Type 1 eigenfunctions):\n#       Theta = sinh(sqrt(Da) r)/(r sinh sqrt(Da)) + 2 sum_n (n pi)(-1)^n/((n pi)^2 + Da)\n#               * exp(-((n pi)^2 + Da) t) sin(n pi r)/r\n#   * polar problem (eta = cos(theta), w = 1, p = 1 - eta^2): Legendre polynomials P_n, lambda^2 = n(n+1),\n#       int_-1^1 P_n P_m d eta = 2/(2n+1) delta_nm\n#   * Ex 3, sphere (conductivity k_B) in a matrix (k_A) under a uniform gradient G, gamma = k_B/k_A:\n#       outside T = G r cos(theta) [1 + ((1 - gamma)/(2 + gamma)) (R/r)^3],  inside T = G r cos(theta) 3/(2 + gamma)\n#       -> Maxwell's effective conductivity of a dilute suspension (volume fraction f):\n#       k_eff/k_A = (gamma + 2 + 2 f (gamma - 1)) / (gamma + 2 - f (gamma - 1))\n\nimport math\n\n\ndef steady_profile(r, Da):\n    p = math.sqrt(Da)\n    if r < 1e-12:\n        return p / math.sinh(p)\n    return math.sinh(p * r) / (r * math.sinh(p))\n\n\ndef effectiveness(phi):\n    return 3.0 * (phi / math.tanh(phi) - 1.0) / phi ** 2\n\n\ndef transient(r, t, Da, nterms=400):\n    s = steady_profile(r, Da)\n    for n in range(1, nterms + 1):\n        a = n * math.pi\n        shape = a if r < 1e-12 else math.sin(a * r) / r\n        s += 2.0 * a * (-1) ** n / (a * a + Da) * math.exp(-(a * a + Da) * t) * shape\n    return s\n\n\ndef fv_transient(t_end, Da, N=60):\n    dr = 1.0 / N\n    steps = int(t_end / (0.15 * dr * dr)) + 1\n    dt = t_end / steps\n    rc = [(i + 0.5) * dr for i in range(N)]\n    vol = [((i + 1) ** 3 - i ** 3) * dr ** 3 / 3.0 for i in range(N)]\n    th = [0.0] * N\n    for _ in range(steps):\n        new = th[:]\n        for i in range(N):\n            aw, ae = (i * dr) ** 2, ((i + 1) * dr) ** 2\n            fw = aw * (th[i] - th[i - 1]) / dr if i > 0 else 0.0\n            fe = ae * ((th[i + 1] if i < N - 1 else 1.0) - th[i]) / (dr if i < N - 1 else dr / 2)\n            new[i] = th[i] + dt * ((fe - fw) / vol[i] - Da * th[i])\n        th = new\n    return rc, th\n\n\ndef legendre(n, x):\n    p0, p1 = 1.0, x\n    if n == 0:\n        return p0\n    for k in range(1, n):\n        p0, p1 = p1, ((2 * k + 1) * x * p1 - k * p0) / (k + 1)\n    return p1\n\n\ndef gauss_legendre_integral(f, m=40):\n    # composite Simpson on [-1, 1] is adequate for polynomial products of low order\n    n = 2 * m\n    h = 2.0 / n\n    s = f(-1.0) + f(1.0)\n    for i in range(1, n):\n        s += (4 if i % 2 else 2) * f(-1.0 + i * h)\n    return s * h / 3\n\n\ndef maxwell(gamma, f):\n    return (gamma + 2 + 2 * f * (gamma - 1)) / (gamma + 2 - f * (gamma - 1))\n\n\nif __name__ == \"__main__\":\n    print(\"=== 1. Steady reaction in a sphere: profile and effectiveness factor ===\")\n    for Da in (0.25, 1.0, 9.0, 100.0):\n        phi = math.sqrt(Da)\n        print(f\"  Da = {Da:6.2f} (phi = {phi:5.2f}): centre Theta = {steady_profile(0, Da):.4f}, \"\n              f\"eta = {effectiveness(phi):.4f}, large-phi limit 3/phi = {3/phi:.4f}\")\n\n    print(\"\\n=== 2. Transient start-up (Ex 2): series vs finite volume, Da = 9 ===\")\n    Da = 9.0\n    for t in (0.02, 0.1, 0.5):\n        rc, th = fv_transient(t, Da)\n        print(f\"  t = {t:4.2f}: centre series = {transient(0, t, Da):.5f}, FV = {th[0]:.5f}  \"\n              f\"(steady {steady_profile(0, Da):.5f})\")\n    print(f\"  check t = 0: Theta(0.5, 0) = {transient(0.5, 0.0, Da, 4000):.4f} (should be 0)\")\n    print(f\"  slowest decay rate pi^2 + Da = {math.pi**2 + Da:.3f}: reaction speeds up the approach to steady state\")\n\n    print(\"\\n=== 3. Radial eigenvalues of a sphere ===\")\n    def root(f, a, b):\n        for _ in range(100):\n            c = 0.5 * (a + b)\n            if f(a) * f(c) <= 0:\n                b = c\n            else:\n                a = c\n        return 0.5 * (a + b)\n    t2 = [root(lambda x: math.sin(x) - x * math.cos(x), (k + 0.5) * math.pi - 0.5, (k + 0.5) * math.pi - 1e-9) for k in range(1, 4)]\n    print(\"  Type 1: n pi =\", [round(k * math.pi, 4) for k in range(1, 4)])\n    print(\"  Type 2 (lambda = tan lambda):\", [round(v, 4) for v in t2])\n\n    print(\"\\n=== 4. Legendre polynomials: orthogonality ===\")\n    for n in range(4):\n        row = [gauss_legendre_integral(lambda x: legendre(n, x) * legendre(m, x)) for m in range(4)]\n        print(\"  \", \" \".join(f\"{v:+.4f}\" for v in row), f\"   2/(2n+1) = {2/(2*n+1):.4f}\")\n\n    print(\"\\n=== 5. Sphere in a gradient: Maxwell effective conductivity ===\")\n    print(\"  gamma = kB/kA   inside gradient 3/(2+gamma)   k_eff/k_A at f = 0.1, 0.3\")\n    for gamma in (0.0, 0.1, 1.0, 10.0, 100.0):\n        print(f\"  {gamma:7.1f}          {3/(2+gamma):.4f}                  {maxwell(gamma,0.1):.4f}, {maxwell(gamma,0.3):.4f}\")\n    print(\"  case: thermal interface material, epoxy kA = 0.2 W/m/K with alumina kB = 30 W/m/K\")\n    for f in (0.1, 0.3, 0.5):\n        print(f\"    f = {f:.1f}: k_eff = {0.2*maxwell(150.0, f):.3f} W/m/K\")\n    print(\"  -> even very conductive fillers raise k_eff by at most (1 + 2f)/(1 - f) in the dilute model\")\n",
    matlab: "% Week 11 - Topic 4: Spherical Coordinates - Reaction in a Catalyst Pellet and Legendre Polynomials\n% Lecture (Part 3):\n%   * radial problem (w = r^2, p = r^2): (1/r^2)(r^2 F')' = -lambda^2 F -> F = sin(lambda r)/r (spherical Bessel j0)\n%       Type 1 F(1) = 0: lambda_n = n pi;  Type 2 F'(1) = 0: lambda = tan(lambda);\n%       Type 3 F'(1) + A F(1) = 0: lambda = (1 - A) tan(lambda)\n%   * Ex 1, steady first-order reaction in a sphere, Da = k R^2/D (= phi^2, Thiele modulus squared):\n%       Theta = sinh(sqrt(Da) r)/(r sinh(sqrt(Da))),  effectiveness eta = 3 (phi coth phi - 1)/phi^2\n%   * Ex 2, transient start-up, Theta(r,0) = 0:\n%       Theta = steady + 2 sum_n (n pi)(-1)^n/((n pi)^2 + Da) exp(-((n pi)^2 + Da) t) sin(n pi r)/r\n%   * polar problem (eta = cos(theta)): Legendre polynomials, int P_n P_m = 2/(2n+1) delta_nm\n%   * Ex 3, sphere (k_B) in a matrix (k_A) under a uniform gradient, gamma = k_B/k_A:\n%       inside gradient = 3/(2 + gamma);  Maxwell: k_eff/k_A = (gamma + 2 + 2f(gamma - 1))/(gamma + 2 - f(gamma - 1))\n% Run: week11_topic4_sphere_reaction_legendre   (MATLAB R2016b or later)\n\nfprintf('=== 1. Steady reaction in a sphere: profile and effectiveness factor ===\\n');\nfor Da = [0.25 1 9 100]\n    phi = sqrt(Da);\n    fprintf('  Da = %6.2f (phi = %5.2f): centre Theta = %.4f, eta = %.4f, large-phi limit 3/phi = %.4f\\n', ...\n        Da, phi, steady_profile(0, Da), 3*(phi/tanh(phi) - 1)/phi^2, 3/phi);\nend\n\nfprintf('\\n=== 2. Transient start-up (Ex 2): series vs finite volume, Da = 9 ===\\n');\nDa = 9;\nfor t = [0.02 0.1 0.5]\n    th = fv_transient(t, Da, 60);\n    fprintf('  t = %4.2f: centre series = %.5f, FV = %.5f  (steady %.5f)\\n', t, transient(0, t, Da, 400), th(1), steady_profile(0, Da));\nend\nfprintf('  check t = 0: Theta(0.5, 0) = %.4f (should be 0)\\n', transient(0.5, 0, Da, 4000));\nfprintf('  slowest decay rate pi^2 + Da = %.3f: reaction speeds up the approach to steady state\\n', pi^2 + Da);\n\nfprintf('\\n=== 3. Radial eigenvalues of a sphere ===\\n');\nfprintf('  Type 1: n pi = [%.4f, %.4f, %.4f]\\n', pi, 2*pi, 3*pi);\ng = @(x) sin(x) - x.*cos(x);\nt2 = arrayfun(@(k) fzero(g, [(k+0.5)*pi-0.5, (k+0.5)*pi-1e-9]), 1:3);\nfprintf('  Type 2 (lambda = tan lambda): [%.4f, %.4f, %.4f]\\n', t2);\n\nfprintf('\\n=== 4. Legendre polynomials: orthogonality ===\\n');\nfor n = 0:3\n    fprintf('  ');\n    for m = 0:3\n        fprintf(' %+.4f', integral(@(x) legendreP(n, x).*legendreP(m, x), -1, 1));\n    end\n    fprintf('    2/(2n+1) = %.4f\\n', 2/(2*n+1));\nend\n\nfprintf('\\n=== 5. Sphere in a gradient: Maxwell effective conductivity ===\\n');\nfprintf('  gamma = kB/kA   inside gradient 3/(2+gamma)   k_eff/k_A at f = 0.1, 0.3\\n');\nmx = @(g, f) (g + 2 + 2*f*(g - 1))./(g + 2 - f*(g - 1));\nfor gm = [0 0.1 1 10 100]\n    fprintf('  %7.1f          %.4f                  %.4f, %.4f\\n', gm, 3/(2+gm), mx(gm, 0.1), mx(gm, 0.3));\nend\nfprintf('  case: thermal interface material, epoxy kA = 0.2 W/m/K with alumina kB = 30 W/m/K\\n');\nfor f = [0.1 0.3 0.5]\n    fprintf('    f = %.1f: k_eff = %.3f W/m/K\\n', f, 0.2*mx(150, f));\nend\nfprintf('  -> even very conductive fillers raise k_eff by at most (1 + 2f)/(1 - f) in the dilute model\\n');\n\n% ------------------------------------------------------------------ local functions\nfunction v = steady_profile(r, Da)\n    p = sqrt(Da);\n    if r < 1e-12, v = p/sinh(p); else, v = sinh(p*r)/(r*sinh(p)); end\nend\n\nfunction s = transient(r, t, Da, nterms)\n    s = steady_profile(r, Da);\n    for n = 1:nterms\n        a = n*pi;\n        if r < 1e-12, shape = a; else, shape = sin(a*r)/r; end\n        s = s + 2*a*(-1)^n/(a^2 + Da)*exp(-(a^2 + Da)*t)*shape;\n    end\nend\n\nfunction th = fv_transient(tEnd, Da, N)\n    dr = 1/N; steps = floor(tEnd/(0.15*dr^2)) + 1; dt = tEnd/steps;\n    i = 0:N-1;\n    vol = ((i+1).^3 - i.^3)*dr^3/3;\n    aw = (i*dr).^2; ae = ((i+1)*dr).^2;\n    th = zeros(1, N);\n    for s = 1:steps\n        fw = [0, aw(2:N).*(th(2:N) - th(1:N-1))/dr];\n        fe = [ae(1:N-1).*(th(2:N) - th(1:N-1))/dr, ae(N)*(1 - th(N))/(dr/2)];\n        th = th + dt*((fe - fw)./vol - Da*th);\n    end\nend\n\nfunction p = legendreP(n, x)\n    p0 = ones(size(x)); p1 = x;\n    if n == 0, p = p0; return; end\n    for k = 1:n-1\n        p2 = ((2*k + 1)*x.*p1 - k*p0)/(k + 1);\n        p0 = p1; p1 = p2;\n    end\n    p = p1;\nend\n",
    julia: "# Week 11 - Topic 4: Spherical Coordinates - Reaction in a Catalyst Pellet and Legendre Polynomials\n# Lecture (Part 3):\n#   * radial problem (w = r^2, p = r^2): (1/r^2)(r^2 F')' = -lambda^2 F -> F = sin(lambda r)/r (spherical Bessel j0)\n#       Type 1 F(1) = 0: lambda_n = n pi;  Type 2 F'(1) = 0: lambda = tan(lambda);\n#       Type 3 F'(1) + A F(1) = 0: lambda = (1 - A) tan(lambda)\n#   * Ex 1, steady first-order reaction in a sphere, Da = k R^2/D (= phi^2, Thiele modulus squared):\n#       Theta = sinh(sqrt(Da) r)/(r sinh(sqrt(Da))),  effectiveness eta = 3 (phi coth phi - 1)/phi^2\n#   * Ex 2, transient start-up, Theta(r,0) = 0:\n#       Theta = steady + 2 sum_n (n pi)(-1)^n/((n pi)^2 + Da) exp(-((n pi)^2 + Da) t) sin(n pi r)/r\n#   * polar problem (eta = cos(theta)): Legendre polynomials, int P_n P_m = 2/(2n+1) delta_nm\n#   * Ex 3, sphere (k_B) in a matrix (k_A) under a uniform gradient, gamma = k_B/k_A:\n#       inside gradient = 3/(2 + gamma);  Maxwell: k_eff/k_A = (gamma + 2 + 2f(gamma - 1))/(gamma + 2 - f(gamma - 1))\n# Run: julia week11_topic4_sphere_reaction_legendre.jl\n\nusing Printf\n\nfunction steady_profile(r, Da)\n    p = sqrt(Da)\n    return r < 1e-12 ? p / sinh(p) : sinh(p * r) / (r * sinh(p))\nend\n\neffectiveness(phi) = 3 * (phi / tanh(phi) - 1) / phi^2\n\nfunction transient(r, t, Da; nterms=400)\n    s = steady_profile(r, Da)\n    for n in 1:nterms\n        a = n * pi\n        shape = r < 1e-12 ? a : sin(a * r) / r\n        s += 2 * a * (isodd(n) ? -1.0 : 1.0) / (a^2 + Da) * exp(-(a^2 + Da) * t) * shape\n    end\n    return s\nend\n\nfunction fv_transient(tEnd, Da; N=60)\n    dr = 1 / N\n    steps = floor(Int, tEnd / (0.15 * dr^2)) + 1\n    dt = tEnd / steps\n    vol = [((i + 1)^3 - i^3) * dr^3 / 3 for i in 0:N-1]\n    th = zeros(N); nw = zeros(N)\n    for _ in 1:steps\n        for i in 1:N\n            aw, ae = ((i - 1) * dr)^2, (i * dr)^2\n            fw = i > 1 ? aw * (th[i] - th[i-1]) / dr : 0.0\n            fe = i < N ? ae * (th[i+1] - th[i]) / dr : ae * (1.0 - th[i]) / (dr / 2)\n            nw[i] = th[i] + dt * ((fe - fw) / vol[i] - Da * th[i])\n        end\n        th .= nw\n    end\n    return th\nend\n\nfunction legendre(n, x)\n    n == 0 && return 1.0\n    p0, p1 = 1.0, x\n    for k in 1:n-1\n        p0, p1 = p1, ((2k + 1) * x * p1 - k * p0) / (k + 1)\n    end\n    return p1\nend\n\nfunction simpson_pm1(f; m=40)\n    n = 2m; h = 2.0 / n\n    s = f(-1.0) + f(1.0)\n    for i in 1:n-1\n        s += (isodd(i) ? 4 : 2) * f(-1.0 + i * h)\n    end\n    return s * h / 3\nend\n\nmaxwell(g, f) = (g + 2 + 2f * (g - 1)) / (g + 2 - f * (g - 1))\n\nfunction bisect(f, a, b)\n    for _ in 1:100\n        c = 0.5 * (a + b)\n        f(a) * f(c) <= 0 ? (b = c) : (a = c)\n    end\n    return 0.5 * (a + b)\nend\n\nprintln(\"=== 1. Steady reaction in a sphere: profile and effectiveness factor ===\")\nfor Da in (0.25, 1.0, 9.0, 100.0)\n    phi = sqrt(Da)\n    @printf(\"  Da = %6.2f (phi = %5.2f): centre Theta = %.4f, eta = %.4f, large-phi limit 3/phi = %.4f\\n\",\n            Da, phi, steady_profile(0, Da), effectiveness(phi), 3 / phi)\nend\n\nprintln(\"\\n=== 2. Transient start-up (Ex 2): series vs finite volume, Da = 9 ===\")\nDa = 9.0\nfor t in (0.02, 0.1, 0.5)\n    th = fv_transient(t, Da)\n    @printf(\"  t = %4.2f: centre series = %.5f, FV = %.5f  (steady %.5f)\\n\", t, transient(0, t, Da), th[1], steady_profile(0, Da))\nend\n@printf(\"  check t = 0: Theta(0.5, 0) = %.4f (should be 0)\\n\", transient(0.5, 0.0, Da; nterms=4000))\n@printf(\"  slowest decay rate pi^2 + Da = %.3f: reaction speeds up the approach to steady state\\n\", pi^2 + Da)\n\nprintln(\"\\n=== 3. Radial eigenvalues of a sphere ===\")\n@printf(\"  Type 1: n pi = [%.4f, %.4f, %.4f]\\n\", pi, 2pi, 3pi)\nt2 = [bisect(x -> sin(x) - x * cos(x), (k + 0.5) * pi - 0.5, (k + 0.5) * pi - 1e-9) for k in 1:3]\n@printf(\"  Type 2 (lambda = tan lambda): [%.4f, %.4f, %.4f]\\n\", t2[1], t2[2], t2[3])\n\nprintln(\"\\n=== 4. Legendre polynomials: orthogonality ===\")\nfor n in 0:3\n    print(\"  \")\n    for m in 0:3\n        @printf(\" %+.4f\", simpson_pm1(x -> legendre(n, x) * legendre(m, x)))\n    end\n    @printf(\"    2/(2n+1) = %.4f\\n\", 2 / (2n + 1))\nend\n\nprintln(\"\\n=== 5. Sphere in a gradient: Maxwell effective conductivity ===\")\nprintln(\"  gamma = kB/kA   inside gradient 3/(2+gamma)   k_eff/k_A at f = 0.1, 0.3\")\nfor g in (0.0, 0.1, 1.0, 10.0, 100.0)\n    @printf(\"  %7.1f          %.4f                  %.4f, %.4f\\n\", g, 3 / (2 + g), maxwell(g, 0.1), maxwell(g, 0.3))\nend\nprintln(\"  case: thermal interface material, epoxy kA = 0.2 W/m/K with alumina kB = 30 W/m/K\")\nfor f in (0.1, 0.3, 0.5)\n    @printf(\"    f = %.1f: k_eff = %.3f W/m/K\\n\", f, 0.2 * maxwell(150.0, f))\nend\nprintln(\"  -> even very conductive fillers raise k_eff by at most (1 + 2f)/(1 - f) in the dilute model\")\n",
    cpp: "// Week 11 - Topic 4: Spherical Coordinates - Reaction in a Catalyst Pellet and Legendre Polynomials\n// Lecture (Part 3):\n//   * radial problem (w = r^2, p = r^2): (1/r^2)(r^2 F')' = -lambda^2 F -> F = sin(lambda r)/r (spherical Bessel j0)\n//       Type 1 F(1) = 0: lambda_n = n pi;  Type 2 F'(1) = 0: lambda = tan(lambda);\n//       Type 3 F'(1) + A F(1) = 0: lambda = (1 - A) tan(lambda)\n//   * Ex 1, steady first-order reaction in a sphere, Da = k R^2/D (= phi^2, Thiele modulus squared):\n//       Theta = sinh(sqrt(Da) r)/(r sinh(sqrt(Da))),  effectiveness eta = 3 (phi coth phi - 1)/phi^2\n//   * Ex 2, transient start-up, Theta(r,0) = 0:\n//       Theta = steady + 2 sum_n (n pi)(-1)^n/((n pi)^2 + Da) exp(-((n pi)^2 + Da) t) sin(n pi r)/r\n//   * polar problem (eta = cos(theta)): Legendre polynomials, int P_n P_m = 2/(2n+1) delta_nm\n//   * Ex 3, sphere (k_B) in a matrix (k_A) under a uniform gradient, gamma = k_B/k_A:\n//       inside gradient = 3/(2 + gamma);  Maxwell: k_eff/k_A = (gamma + 2 + 2f(gamma - 1))/(gamma + 2 - f(gamma - 1))\n// Build: g++ -O2 -std=c++17 week11_topic4_sphere_reaction_legendre.cpp -o topic4\n#include <cmath>\n#include <cstdio>\n#include <functional>\n#include <initializer_list>\n#include <vector>\n\nconst double PI = 3.14159265358979323846;\n\ndouble steadyProfile(double r, double Da) {\n    double p = std::sqrt(Da);\n    if (r < 1e-12) return p / std::sinh(p);\n    return std::sinh(p * r) / (r * std::sinh(p));\n}\n\ndouble effectiveness(double phi) { return 3.0 * (phi / std::tanh(phi) - 1.0) / (phi * phi); }\n\ndouble transient(double r, double t, double Da, int nterms = 400) {\n    double s = steadyProfile(r, Da);\n    for (int n = 1; n <= nterms; ++n) {\n        double a = n * PI;\n        double shape = r < 1e-12 ? a : std::sin(a * r) / r;\n        s += 2.0 * a * ((n % 2) ? -1.0 : 1.0) / (a * a + Da) * std::exp(-(a * a + Da) * t) * shape;\n    }\n    return s;\n}\n\nstd::vector<double> fvTransient(double tEnd, double Da, int N = 60) {\n    double dr = 1.0 / N;\n    int steps = int(tEnd / (0.15 * dr * dr)) + 1;\n    double dt = tEnd / steps;\n    std::vector<double> vol(N), th(N, 0.0), nw(N);\n    for (int i = 0; i < N; ++i) vol[i] = (std::pow(i + 1, 3) - std::pow(i, 3)) * dr * dr * dr / 3.0;\n    for (int s = 0; s < steps; ++s) {\n        for (int i = 0; i < N; ++i) {\n            double aw = std::pow(i * dr, 2), ae = std::pow((i + 1) * dr, 2);\n            double fw = i > 0 ? aw * (th[i] - th[i - 1]) / dr : 0.0;\n            double fe = (i < N - 1) ? ae * (th[i + 1] - th[i]) / dr : ae * (1.0 - th[i]) / (dr / 2);\n            nw[i] = th[i] + dt * ((fe - fw) / vol[i] - Da * th[i]);\n        }\n        th = nw;\n    }\n    return th;\n}\n\ndouble legendre(int n, double x) {\n    double p0 = 1.0, p1 = x;\n    if (n == 0) return p0;\n    for (int k = 1; k < n; ++k) {\n        double p2 = ((2 * k + 1) * x * p1 - k * p0) / (k + 1);\n        p0 = p1; p1 = p2;\n    }\n    return p1;\n}\n\ndouble simpsonPM1(const std::function<double(double)>& f, int m = 40) {\n    int n = 2 * m;\n    double h = 2.0 / n, s = f(-1.0) + f(1.0);\n    for (int i = 1; i < n; ++i) s += (i % 2 ? 4 : 2) * f(-1.0 + i * h);\n    return s * h / 3;\n}\n\ndouble maxwell(double g, double f) { return (g + 2 + 2 * f * (g - 1)) / (g + 2 - f * (g - 1)); }\n\ndouble root(const std::function<double(double)>& f, double a, double b) {\n    for (int i = 0; i < 100; ++i) {\n        double c = 0.5 * (a + b);\n        if (f(a) * f(c) <= 0) b = c; else a = c;\n    }\n    return 0.5 * (a + b);\n}\n\nint main() {\n    std::printf(\"=== 1. Steady reaction in a sphere: profile and effectiveness factor ===\\n\");\n    for (double Da : {0.25, 1.0, 9.0, 100.0}) {\n        double phi = std::sqrt(Da);\n        std::printf(\"  Da = %6.2f (phi = %5.2f): centre Theta = %.4f, eta = %.4f, large-phi limit 3/phi = %.4f\\n\",\n                    Da, phi, steadyProfile(0, Da), effectiveness(phi), 3 / phi);\n    }\n\n    std::printf(\"\\n=== 2. Transient start-up (Ex 2): series vs finite volume, Da = 9 ===\\n\");\n    double Da = 9.0;\n    for (double t : {0.02, 0.1, 0.5}) {\n        std::vector<double> th = fvTransient(t, Da);\n        std::printf(\"  t = %4.2f: centre series = %.5f, FV = %.5f  (steady %.5f)\\n\", t, transient(0, t, Da), th[0], steadyProfile(0, Da));\n    }\n    std::printf(\"  check t = 0: Theta(0.5, 0) = %.4f (should be 0)\\n\", transient(0.5, 0.0, Da, 4000));\n    std::printf(\"  slowest decay rate pi^2 + Da = %.3f: reaction speeds up the approach to steady state\\n\", PI * PI + Da);\n\n    std::printf(\"\\n=== 3. Radial eigenvalues of a sphere ===\\n\");\n    std::printf(\"  Type 1: n pi = [%.4f, %.4f, %.4f]\\n\", PI, 2 * PI, 3 * PI);\n    std::printf(\"  Type 2 (lambda = tan lambda): [\");\n    for (int k = 1; k <= 3; ++k)\n        std::printf(\"%s%.4f\", k > 1 ? \", \" : \"\",\n                    root([](double x) { return std::sin(x) - x * std::cos(x); }, (k + 0.5) * PI - 0.5, (k + 0.5) * PI - 1e-9));\n    std::printf(\"]\\n\");\n\n    std::printf(\"\\n=== 4. Legendre polynomials: orthogonality ===\\n\");\n    for (int n = 0; n < 4; ++n) {\n        std::printf(\"  \");\n        for (int m = 0; m < 4; ++m) std::printf(\" %+.4f\", simpsonPM1([&](double x) { return legendre(n, x) * legendre(m, x); }));\n        std::printf(\"    2/(2n+1) = %.4f\\n\", 2.0 / (2 * n + 1));\n    }\n\n    std::printf(\"\\n=== 5. Sphere in a gradient: Maxwell effective conductivity ===\\n\");\n    std::printf(\"  gamma = kB/kA   inside gradient 3/(2+gamma)   k_eff/k_A at f = 0.1, 0.3\\n\");\n    for (double g : {0.0, 0.1, 1.0, 10.0, 100.0})\n        std::printf(\"  %7.1f          %.4f                  %.4f, %.4f\\n\", g, 3 / (2 + g), maxwell(g, 0.1), maxwell(g, 0.3));\n    std::printf(\"  case: thermal interface material, epoxy kA = 0.2 W/m/K with alumina kB = 30 W/m/K\\n\");\n    for (double f : {0.1, 0.3, 0.5}) std::printf(\"    f = %.1f: k_eff = %.3f W/m/K\\n\", f, 0.2 * maxwell(150.0, f));\n    std::printf(\"  -> even very conductive fillers raise k_eff by at most (1 + 2f)/(1 - f) in the dilute model\\n\");\n    return 0;\n}\n",
  },
};

export default WEEK11_CODES;
